-- Step 2 of 2 — run after step 1. All-or-nothing.
-- Generated by scripts/db/bundle-production.mjs from:
--   20261114000000_security_hardening.sql
--   20261114000100_admin.sql
--   20261114000200_customer.sql
--   20261114010100_store_platform.sql
--   20261114020000_search.sql
--   20261114030000_pdp.sql
--   20261114040000_admin_ops.sql
--   20261114050000_admin_catalog.sql
--   20261114060000_orders_i18n_promo.sql
--   20261114070000_checkout.sql
--   20261114080000_security_fixes.sql

BEGIN;

-- ════ 20261114000000_security_hardening.sql ════
-- ══════════════════════════════════════════════════════════════
-- ShiftSouq — Security & checkout hardening (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- Safe to run on an existing database: every step is idempotent.
--
-- 1. Brings the schema in line with what the app already uses
--    (payment columns on orders that were only added by hand).
-- 2. Customers can no longer promote themselves to admin
--    (profile role / identity columns are locked).
-- 3. Customers can no longer insert orders directly (prices would
--    come from the browser). Orders are created only through
--    place_order(), which prices everything from the database,
--    reserves stock and applies promo codes atomically.
-- 4. Promo codes are no longer readable by the public; they are
--    validated server-side (preview_promo / place_order).
-- 5. Stock is released when an unpaid online order expires, fails
--    or is cancelled; paid orders are confirmed by the webhook via
--    mark_order_paid(), which checks the amount.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Orders: payment columns & guest orders ─────────────────
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_status TEXT NOT NULL DEFAULT 'unpaid';
ALTER TABLE orders ADD COLUMN IF NOT EXISTS transaction_id TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_method TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS paymob_order_id TEXT;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS shipping_governorate TEXT;
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'stock_released'
  ) THEN
    ALTER TABLE orders ADD COLUMN stock_released BOOLEAN NOT NULL DEFAULT false;
    -- Orders placed before this migration never reserved stock, so cancelling
    -- one of them must not add stock back. (Runs only when the column is new.)
    UPDATE orders SET stock_released = true;
  END IF;
END $$;
-- Secret handed to the buyer's browser so a guest can pay for / view their own order.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS access_token UUID NOT NULL DEFAULT gen_random_uuid();
-- Guests no longer get (or hijack) a profile: their orders simply have no user.
ALTER TABLE orders ALTER COLUMN user_id DROP NOT NULL;

-- Older orders kept the payment method and governorate only in notes
-- ("Payment: CARD | Gov: cairo"); copy them into the real columns.
UPDATE orders
SET payment_method = lower(substring(notes FROM 'Payment: (COD|CARD|WALLET)'))
WHERE payment_method IS NULL AND notes ~ 'Payment: (COD|CARD|WALLET)';

UPDATE orders
SET shipping_governorate = substring(notes FROM 'Gov: ([a-z_-]+)')
WHERE shipping_governorate IS NULL AND notes ~ 'Gov: [a-z_-]+';

-- Values written by hand or by older code must fit the constraint below.
UPDATE orders SET payment_status = 'unpaid'
WHERE payment_status IS NULL OR payment_status NOT IN ('unpaid', 'paid', 'failed', 'refunded');

DO $$ BEGIN
  ALTER TABLE orders ADD CONSTRAINT orders_payment_status_check
    CHECK (payment_status IN ('unpaid', 'paid', 'failed', 'refunded'));
EXCEPTION WHEN duplicate_object OR invalid_text_representation OR datatype_mismatch THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE orders ADD CONSTRAINT orders_payment_method_check
    CHECK (payment_method IS NULL OR payment_method IN ('cod', 'card', 'wallet'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE orders ADD CONSTRAINT orders_amounts_check
    CHECK (subtotal >= 0 AND total >= 0 AND COALESCE(discount_amount, 0) >= 0 AND COALESCE(shipping_cost, 0) >= 0);
EXCEPTION WHEN duplicate_object OR check_violation THEN NULL; END $$;

CREATE INDEX IF NOT EXISTS idx_orders_payment ON orders(payment_status, created_at);

DO $$ BEGIN
  ALTER TABLE product_variants ADD CONSTRAINT product_variants_stock_check CHECK (stock >= 0);
EXCEPTION WHEN duplicate_object OR check_violation THEN NULL; END $$;

-- ── 2. Profiles: nobody but an admin (or the server) may change role / identity ─
CREATE OR REPLACE FUNCTION public.guard_profile_privileges()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  -- auth.role() is 'anon' / 'authenticated' for API callers, 'service_role' for the
  -- server, and NULL for direct database sessions (migrations, SQL editor).
  IF COALESCE(auth.role(), 'service_role') IN ('anon', 'authenticated') AND NOT public.is_admin() THEN
    IF TG_OP = 'INSERT' THEN
      NEW.role := 'customer';
    ELSIF NEW.role IS DISTINCT FROM OLD.role OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN
      RAISE EXCEPTION 'Not allowed to change role or account link' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_profiles_guard ON profiles;
CREATE TRIGGER trg_profiles_guard
  BEFORE INSERT OR UPDATE ON profiles
  FOR EACH ROW EXECUTE FUNCTION public.guard_profile_privileges();

-- Profile row for every new account, with the names the sign-up form collects.
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  INSERT INTO public.profiles (auth_user_id, full_name, phone, country, city, role)
  VALUES (
    NEW.id,
    NULLIF(TRIM(COALESCE(
      NEW.raw_user_meta_data ->> 'full_name',
      CONCAT_WS(' ', NEW.raw_user_meta_data ->> 'first_name', NEW.raw_user_meta_data ->> 'last_name')
    )), ''),
    NEW.raw_user_meta_data ->> 'phone',
    NEW.raw_user_meta_data ->> 'country',
    NEW.raw_user_meta_data ->> 'city',
    'customer'
  )
  ON CONFLICT (auth_user_id) DO NOTHING;
  RETURN NEW;
END;
$$;

DO $$ BEGIN
  CREATE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ── 3. Orders: no direct inserts from the browser ─────────────
DROP POLICY IF EXISTS "user_create_order" ON orders;

-- ── 4. Promo codes: not publicly listable ─────────────────────
DROP POLICY IF EXISTS "auth_read_promos" ON promocodes;

-- Variants and images only for products that are on sale.
DROP POLICY IF EXISTS "pub_read_variants" ON product_variants;
CREATE POLICY "pub_read_variants" ON product_variants FOR SELECT
  USING (EXISTS (SELECT 1 FROM products p WHERE p.id = product_id AND p.is_active));
DROP POLICY IF EXISTS "pub_read_images" ON product_images;
CREATE POLICY "pub_read_images" ON product_images FOR SELECT
  USING (EXISTS (SELECT 1 FROM products p WHERE p.id = product_id AND p.is_active));

-- ── 5. Stock release for abandoned / failed / cancelled orders ─
-- Puts an order's quantities back on the shelf (does not touch the order row).
CREATE OR REPLACE FUNCTION public.restore_order_stock(p_order_id UUID)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  UPDATE product_variants v
     SET stock = v.stock + oi.quantity
    FROM order_items oi
   WHERE oi.order_id = p_order_id
     AND oi.product_variant_id = v.id;
$$;

CREATE OR REPLACE FUNCTION public.release_order_stock(p_order_id UUID)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Lock the order so two releases can't both restore stock.
  PERFORM 1 FROM orders WHERE id = p_order_id AND NOT stock_released FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  PERFORM public.restore_order_stock(p_order_id);
  UPDATE orders SET stock_released = true WHERE id = p_order_id;
END;
$$;

-- Unpaid card / wallet orders hold stock for one hour, then give it back.
CREATE OR REPLACE FUNCTION public.expire_unpaid_orders()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  r RECORD;
  n integer := 0;
BEGIN
  FOR r IN
    SELECT id FROM orders
     WHERE payment_method IN ('card', 'wallet')
       AND payment_status IN ('unpaid', 'failed')
       AND status = 'pending'
       AND NOT stock_released
       AND created_at < now() - interval '60 minutes'
     FOR UPDATE SKIP LOCKED
  LOOP
    PERFORM public.release_order_stock(r.id);
    UPDATE orders SET status = 'cancelled' WHERE id = r.id;
    n := n + 1;
  END LOOP;
  RETURN n;
END;
$$;

-- Cancelling or refunding an order gives its stock back (admin dashboard).
CREATE OR REPLACE FUNCTION public.restock_on_cancel()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- (Must not UPDATE this same order row from a BEFORE trigger, so restore inline.)
  IF NEW.status IN ('cancelled', 'refunded') AND OLD.status IS DISTINCT FROM NEW.status AND NOT NEW.stock_released THEN
    PERFORM public.restore_order_stock(NEW.id);
    NEW.stock_released := true;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_orders_restock ON orders;
CREATE TRIGGER trg_orders_restock
  BEFORE UPDATE OF status ON orders
  FOR EACH ROW EXECUTE FUNCTION public.restock_on_cancel();

-- ── 6. Promo preview (validation only, no side effects) ───────
CREATE OR REPLACE FUNCTION public.preview_promo(p_code TEXT, p_subtotal NUMERIC)
RETURNS TABLE (ok BOOLEAN, reason TEXT, discount NUMERIC, code TEXT)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  pc promocodes%ROWTYPE;
BEGIN
  SELECT * INTO pc FROM promocodes WHERE lower(promocodes.code) = lower(trim(p_code)) LIMIT 1;
  IF NOT FOUND OR NOT pc.is_active THEN
    RETURN QUERY SELECT false, 'invalid', 0::numeric, NULL::text; RETURN;
  END IF;
  IF pc.expires_at IS NOT NULL AND pc.expires_at <= now() THEN
    RETURN QUERY SELECT false, 'expired', 0::numeric, NULL::text; RETURN;
  END IF;
  IF pc.max_uses IS NOT NULL AND COALESCE(pc.current_uses, 0) >= pc.max_uses THEN
    RETURN QUERY SELECT false, 'used_up', 0::numeric, NULL::text; RETURN;
  END IF;
  IF p_subtotal < COALESCE(pc.min_order_amount, 0) THEN
    RETURN QUERY SELECT false, 'min_order', pc.min_order_amount, NULL::text; RETURN;
  END IF;
  RETURN QUERY SELECT true, NULL::text,
    LEAST(p_subtotal, ROUND(CASE WHEN pc.discount_type = 'percentage'
                                  THEN p_subtotal * pc.discount_value / 100
                                  ELSE pc.discount_value END, 2)),
    pc.code;
END;
$$;

-- ── 7. place_order: the only way an order is created ─────────
-- Called by the server (service role) after it has authenticated the buyer.
-- Prices, stock, discount and totals all come from the database.
CREATE OR REPLACE FUNCTION public.place_order(
  p_user_id        UUID,     -- profiles.id of the signed-in buyer, or NULL for a guest
  p_items          JSONB,    -- [{ "product_id": uuid, "variant_id": uuid|null, "quantity": int }]
  p_shipping_cost  NUMERIC,  -- computed by the server from its shipping table
  p_payment_method TEXT,     -- 'cod' | 'card' | 'wallet'
  p_contact        JSONB,    -- name, phone, email, governorate, city, address, notes
  p_promo_code     TEXT DEFAULT NULL
)
RETURNS TABLE (order_id UUID, order_number TEXT, total NUMERIC, access_token UUID)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
#variable_conflict use_column
DECLARE
  it         JSONB;
  v          RECORD;
  v_variant  UUID;
  v_count    INT;
  qty        INT;
  price      NUMERIC;
  v_subtotal NUMERIC := 0;
  v_discount NUMERIC := 0;
  v_total    NUMERIC;
  v_promo    promocodes%ROWTYPE;
  v_order    orders%ROWTYPE;
  v_number   TEXT;
  lines      JSONB := '[]'::jsonb;
BEGIN
  IF p_payment_method NOT IN ('cod', 'card', 'wallet') THEN
    RAISE EXCEPTION 'invalid_payment_method' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 OR jsonb_array_length(p_items) > 50 THEN
    RAISE EXCEPTION 'empty_cart' USING ERRCODE = '22023';
  END IF;
  IF p_shipping_cost IS NULL OR p_shipping_cost < 0 THEN
    RAISE EXCEPTION 'invalid_shipping' USING ERRCODE = '22023';
  END IF;

  -- Give back stock held by abandoned online orders before checking availability.
  PERFORM public.expire_unpaid_orders();

  -- Price and reserve every line. Rows are locked in a stable order to avoid deadlocks.
  FOR it IN SELECT value FROM jsonb_array_elements(p_items)
             ORDER BY value ->> 'product_id', value ->> 'variant_id'
  LOOP
    qty := (it ->> 'quantity')::int;
    IF qty IS NULL OR qty < 1 OR qty > 99 THEN
      RAISE EXCEPTION 'invalid_quantity' USING ERRCODE = '22023';
    END IF;

    -- Products without options are added to the cart without a variant: use their only variant.
    v_variant := NULLIF(it ->> 'variant_id', '')::uuid;
    IF v_variant IS NULL THEN
      SELECT count(*), min(id::text)::uuid INTO v_count, v_variant
        FROM product_variants WHERE product_id = NULLIF(it ->> 'product_id', '')::uuid;
      IF v_count <> 1 THEN
        RAISE EXCEPTION 'choose_variant:%', it ->> 'product_id' USING ERRCODE = 'P0001';
      END IF;
    END IF;

    SELECT pv.id, pv.stock, pv.size, pv.color_en, pv.price_override,
           p.id AS product_id, p.name_en, p.base_price, p.sale_price, p.is_active,
           (SELECT url FROM product_images pi WHERE pi.product_id = p.id
             ORDER BY pi.is_primary DESC, pi.sort_order LIMIT 1) AS image_url
      INTO v
      FROM product_variants pv
      JOIN products p ON p.id = pv.product_id
     WHERE pv.id = v_variant
       FOR UPDATE OF pv;

    IF NOT FOUND OR NOT v.is_active THEN
      RAISE EXCEPTION 'product_unavailable:%', v_variant USING ERRCODE = 'P0001';
    END IF;
    IF COALESCE(v.stock, 0) < qty THEN
      RAISE EXCEPTION 'out_of_stock:%', v_variant USING ERRCODE = 'P0001';
    END IF;

    price := COALESCE(v.price_override,
                      CASE WHEN v.sale_price IS NOT NULL AND v.sale_price > 0 AND v.sale_price < v.base_price
                           THEN v.sale_price ELSE v.base_price END);

    UPDATE product_variants SET stock = stock - qty WHERE id = v.id;
    v_subtotal := v_subtotal + price * qty;

    lines := lines || jsonb_build_object(
      'variant_id', v.id,
      'name', v.name_en,
      'label', NULLIF(CONCAT_WS(' / ', NULLIF(v.size, ''), NULLIF(v.color_en, '')), ''),
      'price', price,
      'quantity', qty,
      'image', v.image_url
    );
  END LOOP;

  -- Promo code (locked so max_uses can't be exceeded by concurrent orders).
  IF p_promo_code IS NOT NULL AND trim(p_promo_code) <> '' THEN
    SELECT * INTO v_promo FROM promocodes
     WHERE lower(code) = lower(trim(p_promo_code)) FOR UPDATE;
    IF NOT FOUND OR NOT v_promo.is_active
       OR (v_promo.expires_at IS NOT NULL AND v_promo.expires_at <= now())
       OR (v_promo.max_uses IS NOT NULL AND COALESCE(v_promo.current_uses, 0) >= v_promo.max_uses)
       OR v_subtotal < COALESCE(v_promo.min_order_amount, 0) THEN
      RAISE EXCEPTION 'invalid_promo' USING ERRCODE = 'P0001';
    END IF;
    v_discount := LEAST(v_subtotal, ROUND(CASE WHEN v_promo.discount_type = 'percentage'
                                               THEN v_subtotal * v_promo.discount_value / 100
                                               ELSE v_promo.discount_value END, 2));
    UPDATE promocodes SET current_uses = COALESCE(current_uses, 0) + 1 WHERE id = v_promo.id;
  END IF;

  v_total := v_subtotal - v_discount + p_shipping_cost;

  -- Human-readable, collision-checked order number: SS-YYYYMMDD-XXXXXX
  LOOP
    v_number := 'SS-' || to_char(now() AT TIME ZONE 'Africa/Cairo', 'YYYYMMDD') || '-' ||
                upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
    EXIT WHEN NOT EXISTS (SELECT 1 FROM orders o WHERE o.order_number = v_number);
  END LOOP;

  INSERT INTO orders (
    user_id, order_number, status, payment_status, payment_method,
    subtotal, discount_amount, shipping_cost, tax_amount, total, promocode_id,
    shipping_name, shipping_phone, shipping_email, shipping_country,
    shipping_governorate, shipping_city, shipping_address, notes
  ) VALUES (
    p_user_id, v_number, 'pending', 'unpaid', p_payment_method,
    v_subtotal, v_discount, p_shipping_cost, 0, v_total, v_promo.id,
    p_contact ->> 'name', p_contact ->> 'phone', p_contact ->> 'email', 'EG',
    p_contact ->> 'governorate', p_contact ->> 'city', p_contact ->> 'address', p_contact ->> 'notes'
  )
  RETURNING * INTO v_order;

  INSERT INTO order_items (order_id, product_variant_id, product_name, variant_label, unit_price, quantity, image_url)
  SELECT v_order.id, (l ->> 'variant_id')::uuid, l ->> 'name', l ->> 'label',
         (l ->> 'price')::numeric, (l ->> 'quantity')::int, l ->> 'image'
    FROM jsonb_array_elements(lines) AS l;

  RETURN QUERY SELECT v_order.id, v_order.order_number, v_order.total, v_order.access_token;
END;
$$;

-- ── 8. mark_order_paid: called by the Paymob webhook after HMAC check ─
CREATE OR REPLACE FUNCTION public.mark_order_paid(
  p_order_id       UUID,
  p_amount_cents   BIGINT,
  p_transaction_id TEXT,
  p_success        BOOLEAN
)
RETURNS TEXT  -- 'paid' | 'already_paid' | 'failed' | 'amount_mismatch' | 'not_found'
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
#variable_conflict use_column
DECLARE
  o orders%ROWTYPE;
BEGIN
  SELECT * INTO o FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN 'not_found'; END IF;
  IF o.payment_status = 'paid' THEN RETURN 'already_paid'; END IF;

  IF NOT p_success THEN
    UPDATE orders SET payment_status = 'failed', transaction_id = p_transaction_id WHERE id = o.id;
    RETURN 'failed';
  END IF;

  IF p_amount_cents <> ROUND(o.total * 100) THEN
    UPDATE orders
       SET payment_status = 'failed', transaction_id = p_transaction_id,
           notes = CONCAT_WS(E'\n', o.notes, format('Amount mismatch: paid %s cents, expected %s', p_amount_cents, ROUND(o.total * 100)))
     WHERE id = o.id;
    RETURN 'amount_mismatch';
  END IF;

  -- If the reservation had already expired, take the stock again (may go negative-safe check).
  IF o.stock_released THEN
    UPDATE product_variants v SET stock = GREATEST(0, v.stock - oi.quantity)
      FROM order_items oi WHERE oi.order_id = o.id AND oi.product_variant_id = v.id;
    UPDATE orders SET stock_released = false WHERE id = o.id;
  END IF;

  UPDATE orders
     SET payment_status = 'paid', transaction_id = p_transaction_id,
         status = CASE WHEN status IN ('pending', 'cancelled') THEN 'confirmed'::order_status ELSE status END
   WHERE id = o.id;
  RETURN 'paid';
END;
$$;

-- Only the server (service role) may call the order functions.
REVOKE ALL ON FUNCTION public.place_order(UUID, JSONB, NUMERIC, TEXT, JSONB, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.mark_order_paid(UUID, BIGINT, TEXT, BOOLEAN) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.release_order_stock(UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.restore_order_stock(UUID) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.expire_unpaid_orders() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.preview_promo(TEXT, NUMERIC) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.place_order(UUID, JSONB, NUMERIC, TEXT, JSONB, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.mark_order_paid(UUID, BIGINT, TEXT, BOOLEAN) TO service_role;
GRANT EXECUTE ON FUNCTION public.release_order_stock(UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.expire_unpaid_orders() TO service_role;
GRANT EXECUTE ON FUNCTION public.preview_promo(TEXT, NUMERIC) TO service_role;

-- ── 9. Contact form: cap message sizes ─────────────────────────
DO $$ BEGIN
  ALTER TABLE contact_messages ADD CONSTRAINT contact_messages_size_check
    CHECK (char_length(name) <= 120 AND char_length(email) <= 254 AND char_length(subject) <= 200 AND char_length(message) <= 5000);
EXCEPTION WHEN duplicate_object OR check_violation OR undefined_table THEN NULL; END $$;

-- ════ 20261114000100_admin.sql ════
-- ══════════════════════════════════════════════════════════════
-- ShiftSouq — Admin dashboard (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- Safe to run more than once (IF NOT EXISTS / OR REPLACE / guarded
-- DO blocks). Run after 20261114000000_security_hardening.sql.
--
-- 1. Contact inbox: read time and archive for contact messages;
--    visitors can only submit new, unread, unarchived messages.
-- 2. Promo codes: one code per spelling regardless of case (checkout
--    matches codes case-insensitively) and sane values.
-- 3. admin_order_stats(): dashboard totals computed in the database,
--    counting only money actually received (paid online, or COD
--    delivered) — admins only.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Contact inbox ──────────────────────────────────────────
ALTER TABLE contact_messages ADD COLUMN IF NOT EXISTS read_at TIMESTAMPTZ;
ALTER TABLE contact_messages ADD COLUMN IF NOT EXISTS archived_at TIMESTAMPTZ;

UPDATE contact_messages SET is_read = false WHERE is_read IS NULL;
ALTER TABLE contact_messages ALTER COLUMN is_read SET DEFAULT false;

CREATE INDEX IF NOT EXISTS idx_contact_messages_inbox
  ON contact_messages (created_at DESC) WHERE archived_at IS NULL;

-- Visitors may only add a fresh message (not mark it read or archived).
DROP POLICY IF EXISTS "public_insert_contact" ON contact_messages;
CREATE POLICY "public_insert_contact" ON contact_messages FOR INSERT
  WITH CHECK (COALESCE(is_read, false) = false AND read_at IS NULL AND archived_at IS NULL);

-- ── 2. Promo codes ────────────────────────────────────────────
-- place_order / preview_promo look codes up with lower(code); two codes
-- that differ only by case would make that lookup ambiguous.
DO $$ BEGIN
  CREATE UNIQUE INDEX IF NOT EXISTS promocodes_code_lower_key ON promocodes (lower(code));
EXCEPTION WHEN unique_violation THEN
  RAISE NOTICE 'promocodes: some codes differ only by letter case — rename them, then run this migration again.';
END $$;

-- Checked for new and edited codes (existing rows are left as they are).
DO $$ BEGIN
  ALTER TABLE promocodes ADD CONSTRAINT promocodes_values_check CHECK (
    discount_value > 0
    AND (discount_type <> 'percentage' OR discount_value <= 100)
    AND COALESCE(min_order_amount, 0) >= 0
    AND (max_uses IS NULL OR max_uses > 0)
    AND COALESCE(current_uses, 0) >= 0
  ) NOT VALID;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ── 3. Dashboard totals ───────────────────────────────────────
-- SECURITY INVOKER: runs with the caller's rights, so row-level security
-- applies too; non-admins are refused outright.
CREATE OR REPLACE FUNCTION public.admin_order_stats()
RETURNS TABLE (
  total_orders      BIGINT,   -- every order
  revenue           NUMERIC,  -- money received: paid online, or COD delivered; not cancelled / refunded
  revenue_orders    BIGINT,   -- orders behind that revenue
  awaiting_payment  BIGINT,   -- card / wallet orders still waiting for the gateway
  to_fulfil         BIGINT,   -- pending / confirmed / processing orders that can be worked on
  cash_to_collect   NUMERIC   -- COD orders on their way (not delivered, not cancelled)
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    count(*)::bigint,
    COALESCE(sum(o.total) FILTER (WHERE r.received), 0)::numeric,
    count(*) FILTER (WHERE r.received)::bigint,
    count(*) FILTER (
      WHERE o.payment_method IN ('card', 'wallet')
        AND o.payment_status IN ('unpaid', 'failed')
        AND o.status = 'pending'
    )::bigint,
    count(*) FILTER (
      WHERE o.status IN ('pending', 'confirmed', 'processing')
        AND (o.payment_status = 'paid' OR o.payment_method IS NULL OR o.payment_method = 'cod')
    )::bigint,
    COALESCE(sum(o.total) FILTER (
      WHERE o.payment_method = 'cod'
        AND o.payment_status = 'unpaid'
        AND o.status IN ('pending', 'confirmed', 'processing', 'shipped')
    ), 0)::numeric
  FROM orders o
  CROSS JOIN LATERAL (
    SELECT (
      o.status NOT IN ('cancelled', 'refunded')
      AND o.payment_status <> 'refunded'
      AND (o.payment_status = 'paid' OR (o.payment_method = 'cod' AND o.status = 'delivered'))
    ) AS received
  ) r;
END;
$$;

REVOKE ALL ON FUNCTION public.admin_order_stats() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_order_stats() TO authenticated, service_role;

-- ════ 20261114000200_customer.sql ════
-- ══════════════════════════════════════════════════════════════
-- ShiftSouq — Customer checkout: saved delivery address (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- "Save this address for future orders" at checkout stores the
-- buyer's delivery address on their own profile, so the next
-- checkout is prefilled. Written by the buyer's own session
-- (existing "user_update_profile" RLS policy); nothing else can
-- read it except the owner and admins (existing select policies).
--
-- Shape: {"governorate": "cairo", "city": "...", "address": "...",
--         "apartment": "...", "postalCode": "..."}
--
-- Idempotent: safe to run more than once.
-- ══════════════════════════════════════════════════════════════

ALTER TABLE profiles ADD COLUMN IF NOT EXISTS default_address JSONB;

DO $$ BEGIN
  ALTER TABLE profiles ADD CONSTRAINT profiles_default_address_check
    CHECK (
      default_address IS NULL
      OR (jsonb_typeof(default_address) = 'object' AND pg_column_size(default_address) <= 2048)
    );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

COMMENT ON COLUMN profiles.default_address IS
  'Delivery address saved at checkout: governorate, city, address, apartment, postalCode.';

-- ════ 20261114010100_store_platform.sql ════
-- ══════════════════════════════════════════════════════════════
-- ShiftSouq — store platform (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- Idempotent. Adds what a professional, white-label store needs:
--   1. Roles: super admin (owner) vs admin (staff); only the
--      super admin can change roles.
--   2. Catalogue: richer product content, colour-specific images,
--      size systems, SEO fields, category flags, collections.
--   3. Store settings (one row) edited by the super admin:
--      announcement, contact, social, shipping, payments, home.
--   4. Reviews with moderation and verified-purchase flag;
--      product rating kept in sync.
--   5. Customer address book, newsletter, admin audit log.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Roles ──────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE auth_user_id = auth.uid() AND role::text IN ('admin', 'super_admin')
  );
$$;

CREATE OR REPLACE FUNCTION public.is_super_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE auth_user_id = auth.uid() AND role::text = 'super_admin'
  );
$$;

GRANT EXECUTE ON FUNCTION public.is_super_admin() TO anon, authenticated, service_role;

-- Only the super admin (or the server / SQL editor) may change roles or account links.
CREATE OR REPLACE FUNCTION public.guard_profile_privileges()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF COALESCE(auth.role(), 'service_role') IN ('anon', 'authenticated') AND NOT public.is_super_admin() THEN
    IF TG_OP = 'INSERT' THEN
      NEW.role := 'customer';
    ELSIF NEW.role IS DISTINCT FROM OLD.role OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN
      RAISE EXCEPTION 'Not allowed to change role or account link' USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- The first admin who can sign in becomes the store owner (only if there is no owner yet).
UPDATE profiles SET role = 'super_admin'
WHERE id = (
    SELECT id FROM profiles
    WHERE role::text = 'admin' AND auth_user_id IS NOT NULL
    ORDER BY created_at LIMIT 1
  )
  AND NOT EXISTS (SELECT 1 FROM profiles WHERE role::text = 'super_admin' AND auth_user_id IS NOT NULL);

-- ── 2. Catalogue ──────────────────────────────────────────────
ALTER TABLE products ADD COLUMN IF NOT EXISTS details_en TEXT;          -- bullet points, one per line
ALTER TABLE products ADD COLUMN IF NOT EXISTS details_ar TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS care_en TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS care_ar TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS tags TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE products ADD COLUMN IF NOT EXISTS size_system TEXT NOT NULL DEFAULT 'apparel';
ALTER TABLE products ADD COLUMN IF NOT EXISTS seo_title_en TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS seo_title_ar TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS seo_description_en TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS seo_description_ar TEXT;

DO $$ BEGIN
  ALTER TABLE products ADD CONSTRAINT products_size_system_check
    CHECK (size_system IN ('apparel', 'shoes', 'kids', 'waist', 'one_size'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE products ADD CONSTRAINT products_prices_check
    CHECK (base_price >= 0 AND (sale_price IS NULL OR sale_price >= 0));
EXCEPTION WHEN duplicate_object OR check_violation THEN NULL; END $$;

CREATE INDEX IF NOT EXISTS idx_products_tags ON products USING gin (tags);

-- Images can belong to one colour (NULL = shown for every colour).
ALTER TABLE product_images ADD COLUMN IF NOT EXISTS color_en TEXT;

ALTER TABLE product_variants ADD COLUMN IF NOT EXISTS position INT NOT NULL DEFAULT 0;

ALTER TABLE categories ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE categories ADD COLUMN IF NOT EXISTS is_featured BOOLEAN NOT NULL DEFAULT false;

DROP POLICY IF EXISTS "pub_read_categories" ON categories;
CREATE POLICY "pub_read_categories" ON categories FOR SELECT USING (is_active OR public.is_admin());

-- Collections: curated product sets for the home page and campaigns.
CREATE TABLE IF NOT EXISTS collections (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  slug           TEXT NOT NULL UNIQUE,
  title_en       TEXT NOT NULL,
  title_ar       TEXT NOT NULL,
  description_en TEXT,
  description_ar TEXT,
  image_url      TEXT,
  is_active      BOOLEAN NOT NULL DEFAULT true,
  sort_order     INT NOT NULL DEFAULT 0,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS collection_products (
  collection_id UUID NOT NULL REFERENCES collections(id) ON DELETE CASCADE,
  product_id    UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  position      INT NOT NULL DEFAULT 0,
  PRIMARY KEY (collection_id, product_id)
);

ALTER TABLE collections ENABLE ROW LEVEL SECURITY;
ALTER TABLE collection_products ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "pub_read_collections" ON collections;
CREATE POLICY "pub_read_collections" ON collections FOR SELECT USING (is_active OR public.is_admin());
DROP POLICY IF EXISTS "admin_collections" ON collections;
CREATE POLICY "admin_collections" ON collections FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS "pub_read_collection_products" ON collection_products;
CREATE POLICY "pub_read_collection_products" ON collection_products FOR SELECT USING (true);
DROP POLICY IF EXISTS "admin_collection_products" ON collection_products;
CREATE POLICY "admin_collection_products" ON collection_products FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());

-- ── 3. Store settings (single row) ────────────────────────────
CREATE TABLE IF NOT EXISTS store_settings (
  id           SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  -- [{ "en": "...", "ar": "..." }]
  announcement JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- { "email", "phone", "whatsapp", "address_en", "address_ar", "hours_en", "hours_ar" }
  contact      JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- { "instagram", "facebook", "tiktok", "x" }
  social       JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- { "default_fee": 100, "free_threshold": 1500, "zones": { "cairo": 50, ... }, "eta_days": { "min": 2, "max": 5 } }
  shipping     JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- { "cod": true, "card": true, "wallet": true }
  payments     JSONB NOT NULL DEFAULT '{"cod": true, "card": true, "wallet": true}'::jsonb,
  -- { "return_days": 14 }
  policies     JSONB NOT NULL DEFAULT '{"return_days": 14}'::jsonb,
  -- { "hero": { "image", "title_en", "title_ar", "subtitle_en", "subtitle_ar", "cta_href" } }
  home         JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- { "low_stock_threshold": 5 }
  inventory    JSONB NOT NULL DEFAULT '{"low_stock_threshold": 5}'::jsonb,
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by   UUID REFERENCES profiles(id) ON DELETE SET NULL
);

INSERT INTO store_settings (id) VALUES (1) ON CONFLICT (id) DO NOTHING;

ALTER TABLE store_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "pub_read_settings" ON store_settings;
CREATE POLICY "pub_read_settings" ON store_settings FOR SELECT USING (true);
DROP POLICY IF EXISTS "owner_update_settings" ON store_settings;
CREATE POLICY "owner_update_settings" ON store_settings FOR UPDATE
  USING (public.is_super_admin()) WITH CHECK (public.is_super_admin());

-- ── 4. Reviews: moderation + verified purchase ────────────────
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS title TEXT;
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'pending';
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS is_verified BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now();

DO $$ BEGIN
  ALTER TABLE reviews ADD CONSTRAINT reviews_status_check CHECK (status IN ('pending', 'approved', 'rejected'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
  ALTER TABLE reviews ADD CONSTRAINT reviews_size_check
    CHECK (char_length(COALESCE(title, '')) <= 120 AND char_length(COALESCE(comment, '')) <= 2000);
EXCEPTION WHEN duplicate_object OR check_violation THEN NULL; END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uq_reviews_user_product ON reviews(user_id, product_id);

-- Visitors see approved reviews; authors see their own; admins see all.
DROP POLICY IF EXISTS "pub_read_reviews" ON reviews;
CREATE POLICY "pub_read_reviews" ON reviews FOR SELECT USING (
  status = 'approved'
  OR user_id IN (SELECT id FROM profiles WHERE auth_user_id = auth.uid())
  OR public.is_admin()
);

-- Customers may only create pending, unverified reviews (the server sets is_verified).
CREATE OR REPLACE FUNCTION public.guard_review_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF COALESCE(auth.role(), 'service_role') IN ('anon', 'authenticated') AND NOT public.is_admin() THEN
    NEW.status := 'pending';
    IF TG_OP = 'INSERT' THEN
      NEW.is_verified := false;
    ELSE
      NEW.is_verified := OLD.is_verified;
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_reviews_guard ON reviews;
CREATE TRIGGER trg_reviews_guard BEFORE INSERT OR UPDATE ON reviews
  FOR EACH ROW EXECUTE FUNCTION public.guard_review_fields();

-- products.rating / review_count follow approved reviews.
CREATE OR REPLACE FUNCTION public.refresh_product_rating()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  pid UUID := COALESCE(NEW.product_id, OLD.product_id);
BEGIN
  UPDATE products p SET
    rating = COALESCE((SELECT round(avg(r.rating)::numeric, 2) FROM reviews r WHERE r.product_id = pid AND r.status = 'approved'), 0),
    review_count = (SELECT count(*) FROM reviews r WHERE r.product_id = pid AND r.status = 'approved')
  WHERE p.id = pid;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_reviews_rating ON reviews;
CREATE TRIGGER trg_reviews_rating AFTER INSERT OR UPDATE OR DELETE ON reviews
  FOR EACH ROW EXECUTE FUNCTION public.refresh_product_rating();

-- ── 5a. Customer address book ─────────────────────────────────
CREATE TABLE IF NOT EXISTS user_addresses (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
  label        TEXT,
  full_name    TEXT NOT NULL,
  phone        TEXT NOT NULL,
  governorate  TEXT NOT NULL,
  city         TEXT NOT NULL,
  address      TEXT NOT NULL,
  apartment    TEXT,
  postal_code  TEXT,
  is_default   BOOLEAN NOT NULL DEFAULT false,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (char_length(full_name) <= 120 AND char_length(address) <= 240 AND char_length(phone) <= 20)
);
CREATE INDEX IF NOT EXISTS idx_user_addresses_user ON user_addresses(user_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_user_addresses_default ON user_addresses(user_id) WHERE is_default;

ALTER TABLE user_addresses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "own_addresses" ON user_addresses;
CREATE POLICY "own_addresses" ON user_addresses FOR ALL
  USING (user_id IN (SELECT id FROM profiles WHERE auth_user_id = auth.uid()))
  WITH CHECK (user_id IN (SELECT id FROM profiles WHERE auth_user_id = auth.uid()));
DROP POLICY IF EXISTS "admin_read_addresses" ON user_addresses;
CREATE POLICY "admin_read_addresses" ON user_addresses FOR SELECT USING (public.is_admin());

-- ── 5b. Newsletter ────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS newsletter_subscribers (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email      TEXT NOT NULL,
  locale     TEXT NOT NULL DEFAULT 'en',
