-- ════ 20261114030000_pdp.sql ════
-- ══════════════════════════════════════════════════════════════
-- ShiftSouq — product page reviews (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- Idempotent. Run after 20261114010100_store_platform.sql.
--   1. reviews.author_name: the public name shown under a review
--      ("Mona B."), written by the server, so the product page
--      never reads customer profiles.
--   2. Reviews are written only by the server (lib/actions/
--      reviews.ts) after it has checked that the buyer received
--      the product. Customers can no longer insert reviews
--      straight through the API (that skipped the purchase check
--      and let anyone choose the name shown).
--   3. Indexes for the product page list and the purchase check.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Public author name ─────────────────────────────────────
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS author_name TEXT;

DO $$ BEGIN
  ALTER TABLE reviews ADD CONSTRAINT reviews_author_name_check
    CHECK (author_name IS NULL OR char_length(author_name) <= 60);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ── 2. No direct inserts by customers ─────────────────────────
-- Reading (approved / own / admin), deleting one's own review and
-- the admin policy are unchanged.
DROP POLICY IF EXISTS "user_create_review" ON reviews;

-- ── 3. Indexes ────────────────────────────────────────────────
-- Approved reviews of one product, newest first.
CREATE INDEX IF NOT EXISTS idx_reviews_product_status ON reviews (product_id, status, created_at DESC);
-- "Has this buyer received this product?" joins order lines by variant.
CREATE INDEX IF NOT EXISTS idx_order_items_variant ON order_items (product_variant_id);

-- ════ 20261114040000_admin_ops.sql ════
-- ══════════════════════════════════════════════════════════════
-- ShiftSouq — Admin operations (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- Idempotent (CREATE OR REPLACE / IF NOT EXISTS / DROP … IF EXISTS).
-- Run after 20261114010100_store_platform.sql.
--
-- 1. Order rules in SQL, shared by every report below:
--      order_counts_as_revenue()  money received and the order stands
--      order_is_placed()          not an unpaid card / wallet attempt
-- 2. Dashboard (admins only, row-level security applies):
--      admin_period_stats()   orders, revenue, new customers for a period
--      admin_daily_revenue()  revenue per day (store time zone)
--      admin_top_products()   best sellers by units
--      admin_queue_counts()   work queues + sidebar counters
-- 3. Customers and team (admins only; read e-mail from auth.users):
--      admin_customers()        list / one customer with order totals
--      admin_profile_emails()   e-mail + last sign-in for profile ids
--      admin_profile_by_email() owner only: find an account to add
-- 4. Ownership:
--      transfer_store_ownership()  owner hands the store to an admin
--      guard_last_owner trigger    the store always keeps one owner
-- 5. Indexes for the admin lists.
-- Nothing here is granted to anon.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Order rules ────────────────────────────────────────────
-- Same rule as admin_order_stats() and lib/admin/orders.ts countsAsRevenue():
-- paid online, or cash on delivery that was delivered; not cancelled / refunded.
CREATE OR REPLACE FUNCTION public.order_counts_as_revenue(p_status TEXT, p_payment_status TEXT, p_payment_method TEXT)
RETURNS BOOLEAN
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT COALESCE(p_status, 'pending') NOT IN ('cancelled', 'refunded')
     AND COALESCE(p_payment_status, 'unpaid') <> 'refunded'
     AND (COALESCE(p_payment_status, 'unpaid') = 'paid'
          OR (p_payment_method = 'cod' AND p_status = 'delivered'));
$$;

-- An order the customer actually placed: cash on delivery, or an online
-- order whose payment went through (even if refunded later). Card / wallet
-- orders still waiting for (or abandoned at) the gateway are not counted.
CREATE OR REPLACE FUNCTION public.order_is_placed(p_payment_status TEXT, p_payment_method TEXT)
RETURNS BOOLEAN
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT NOT (COALESCE(p_payment_method, 'cod') IN ('card', 'wallet')
              AND COALESCE(p_payment_status, 'unpaid') IN ('unpaid', 'failed'));
$$;

-- ── 2a. Period totals (dashboard KPIs) ────────────────────────
CREATE OR REPLACE FUNCTION public.admin_period_stats(p_from TIMESTAMPTZ, p_to TIMESTAMPTZ)
RETURNS TABLE (
  orders          BIGINT,   -- orders placed in the period (order_is_placed)
  revenue         NUMERIC,  -- money received for orders placed in the period
  revenue_orders  BIGINT,   -- orders behind that revenue (for the average order value)
  new_customers   BIGINT    -- customer accounts created in the period
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from OR p_to - p_from > interval '400 days' THEN
    RAISE EXCEPTION 'invalid period' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    count(*) FILTER (WHERE public.order_is_placed(o.payment_status, o.payment_method))::bigint,
    COALESCE(sum(o.total) FILTER (WHERE public.order_counts_as_revenue(o.status::text, o.payment_status, o.payment_method)), 0)::numeric,
    count(*) FILTER (WHERE public.order_counts_as_revenue(o.status::text, o.payment_status, o.payment_method))::bigint,
    (SELECT count(*) FROM profiles p
      WHERE p.role::text = 'customer' AND p.created_at >= p_from AND p.created_at < p_to)::bigint
  FROM orders o
  WHERE o.created_at >= p_from AND o.created_at < p_to;
END;
$$;

-- ── 2b. Revenue per day (last N days, store time zone) ────────
CREATE OR REPLACE FUNCTION public.admin_daily_revenue(p_days INT DEFAULT 30, p_tz TEXT DEFAULT 'Africa/Cairo')
RETURNS TABLE (day DATE, revenue NUMERIC, orders BIGINT)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  today DATE;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_days IS NULL OR p_days < 1 OR p_days > 366 THEN
    RAISE EXCEPTION 'invalid number of days' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = p_tz) THEN
    RAISE EXCEPTION 'unknown time zone' USING ERRCODE = '22023';
  END IF;
  today := (now() AT TIME ZONE p_tz)::date;

  RETURN QUERY
  WITH days AS (
    SELECT (today - g)::date AS d FROM generate_series(0, p_days - 1) AS g
  )
  SELECT
    days.d,
    COALESCE(sum(o.total) FILTER (WHERE public.order_counts_as_revenue(o.status::text, o.payment_status, o.payment_method)), 0)::numeric,
    count(o.id) FILTER (WHERE public.order_is_placed(o.payment_status, o.payment_method))::bigint
  FROM days
  LEFT JOIN orders o
    ON o.created_at >= (days.d::timestamp AT TIME ZONE p_tz)
   AND o.created_at <  ((days.d + 1)::timestamp AT TIME ZONE p_tz)
  GROUP BY days.d
  ORDER BY days.d;
END;
$$;

-- ── 2c. Best sellers by units ─────────────────────────────────
-- Items whose product was deleted are grouped by the name kept on the order.
CREATE OR REPLACE FUNCTION public.admin_top_products(p_from TIMESTAMPTZ, p_to TIMESTAMPTZ, p_limit INT DEFAULT 5)
RETURNS TABLE (
  product_id UUID,
  name_en    TEXT,
  name_ar    TEXT,
  slug       TEXT,
  image_url  TEXT,
  units      BIGINT,
  revenue    NUMERIC
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from OR p_to - p_from > interval '400 days' THEN
    RAISE EXCEPTION 'invalid period' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    COALESCE(max(p.name_en), max(oi.product_name)),
    COALESCE(max(p.name_ar), max(oi.product_name)),
    max(p.slug),
    COALESCE(
      (SELECT pi.url FROM product_images pi WHERE pi.product_id = p.id
        ORDER BY pi.is_primary DESC NULLS LAST, pi.sort_order NULLS LAST LIMIT 1),
      max(oi.image_url)
    ),
    sum(oi.quantity)::bigint,
    sum(oi.quantity * oi.unit_price)::numeric
  FROM order_items oi
  JOIN orders o ON o.id = oi.order_id
  LEFT JOIN product_variants v ON v.id = oi.product_variant_id
  LEFT JOIN products p ON p.id = v.product_id
  WHERE o.created_at >= p_from AND o.created_at < p_to
    AND o.status::text NOT IN ('cancelled', 'refunded')
    AND public.order_is_placed(o.payment_status, o.payment_method)
  GROUP BY p.id, CASE WHEN p.id IS NULL THEN oi.product_name END
  ORDER BY 6 DESC, 7 DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 5), 1), 50);
END;
$$;

-- ── 2d. Work queues (dashboard + sidebar counters) ────────────
CREATE OR REPLACE FUNCTION public.admin_queue_counts()
RETURNS TABLE (
  to_fulfil            BIGINT,   -- pending / confirmed / processing orders that can be worked on
  awaiting_payment     BIGINT,   -- card / wallet orders still waiting for the gateway
  cash_to_collect      BIGINT,   -- COD orders on their way, cash not yet collected
  low_stock            BIGINT,   -- variants of live products at or below the threshold
  pending_reviews      BIGINT,
  unread_messages      BIGINT,
  low_stock_threshold  INT
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  threshold INT := 5;
  raw JSONB;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;

  SELECT s.inventory -> 'low_stock_threshold' INTO raw FROM store_settings s WHERE s.id = 1;
  IF raw IS NOT NULL AND jsonb_typeof(raw) = 'number' THEN
    threshold := GREATEST(0, LEAST(1000, floor((raw #>> '{}')::numeric)::int));
  END IF;

  RETURN QUERY
  SELECT
    (SELECT count(*) FROM orders o
      WHERE o.status::text IN ('pending', 'confirmed', 'processing')
        AND (o.payment_status = 'paid' OR o.payment_method IS NULL OR o.payment_method = 'cod'))::bigint,
    (SELECT count(*) FROM orders o
      WHERE o.payment_method IN ('card', 'wallet')
        AND o.payment_status IN ('unpaid', 'failed')
        AND o.status::text = 'pending')::bigint,
    (SELECT count(*) FROM orders o
      WHERE o.payment_method = 'cod' AND o.payment_status = 'unpaid'
        AND o.status::text IN ('shipped', 'delivered'))::bigint,
    (SELECT count(*) FROM product_variants v JOIN products p ON p.id = v.product_id
      WHERE p.is_active IS NOT FALSE AND COALESCE(v.stock, 0) <= threshold)::bigint,
    (SELECT count(*) FROM reviews r WHERE r.status = 'pending')::bigint,
    (SELECT count(*) FROM contact_messages m
      WHERE m.archived_at IS NULL AND COALESCE(m.is_read, false) = false)::bigint,
    threshold;
END;
$$;

-- ── 3a. Customers with order totals ───────────────────────────
-- SECURITY DEFINER only to read e-mail addresses from auth.users;
-- the caller must be an admin (checked first).
CREATE OR REPLACE FUNCTION public.admin_customers(
  p_search TEXT DEFAULT NULL,
  p_digits TEXT DEFAULT NULL,
  p_sort   TEXT DEFAULT 'joined',
  p_desc   BOOLEAN DEFAULT true,
  p_limit  INT DEFAULT 25,
  p_offset INT DEFAULT 0,
  p_id     UUID DEFAULT NULL
)
RETURNS TABLE (
  id              UUID,
  full_name       TEXT,
  email           TEXT,
  phone           TEXT,
  joined_at       TIMESTAMPTZ,
  last_sign_in_at TIMESTAMPTZ,
  orders_count    BIGINT,
  total_spent     NUMERIC,
  last_order_at   TIMESTAMPTZ,
  total_count     BIGINT
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  pattern TEXT;
  digits  TEXT := NULLIF(regexp_replace(COALESCE(p_digits, ''), '\D', '', 'g'), '');
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_search IS NOT NULL AND btrim(p_search) <> '' THEN
    pattern := '%' || replace(replace(replace(left(btrim(p_search), 80), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT
      p.id AS b_id,
      p.full_name AS b_name,
      u.email::text AS b_email,
      p.phone AS b_phone,
      p.created_at AS b_joined,
      u.last_sign_in_at AS b_last_sign_in,
      COALESCE(s.orders_count, 0)::bigint AS b_orders,
      COALESCE(s.total_spent, 0)::numeric AS b_spent,
      s.last_order_at AS b_last_order
    FROM profiles p
    LEFT JOIN auth.users u ON u.id = p.auth_user_id
    LEFT JOIN LATERAL (
      SELECT
        count(*) FILTER (WHERE public.order_is_placed(o.payment_status, o.payment_method)) AS orders_count,
        sum(o.total) FILTER (WHERE public.order_counts_as_revenue(o.status::text, o.payment_status, o.payment_method)) AS total_spent,
        max(o.created_at) FILTER (WHERE public.order_is_placed(o.payment_status, o.payment_method)) AS last_order_at
      FROM orders o
      WHERE o.user_id = p.id
    ) s ON true
    WHERE p.role::text = 'customer'
      AND (p_id IS NULL OR p.id = p_id)
      AND (
        pattern IS NULL
        OR p.full_name ILIKE pattern
        OR u.email ILIKE pattern
        OR p.phone ILIKE pattern
        OR (digits IS NOT NULL AND length(digits) >= 4 AND regexp_replace(COALESCE(p.phone, ''), '\D', '', 'g') LIKE '%' || digits || '%')
      )
  )
  SELECT b.b_id, b.b_name, b.b_email, b.b_phone, b.b_joined, b.b_last_sign_in,
         b.b_orders, b.b_spent, b.b_last_order, count(*) OVER ()::bigint
  FROM base b
  ORDER BY
    CASE WHEN p_sort = 'name'       AND NOT p_desc THEN lower(b.b_name)  END ASC  NULLS LAST,
    CASE WHEN p_sort = 'name'       AND p_desc     THEN lower(b.b_name)  END DESC NULLS LAST,
    CASE WHEN p_sort = 'email'      AND NOT p_desc THEN lower(b.b_email) END ASC  NULLS LAST,
    CASE WHEN p_sort = 'email'      AND p_desc     THEN lower(b.b_email) END DESC NULLS LAST,
    CASE WHEN p_sort = 'orders'     AND NOT p_desc THEN b.b_orders       END ASC  NULLS LAST,
    CASE WHEN p_sort = 'orders'     AND p_desc     THEN b.b_orders       END DESC NULLS LAST,
    CASE WHEN p_sort = 'spent'      AND NOT p_desc THEN b.b_spent        END ASC  NULLS LAST,
    CASE WHEN p_sort = 'spent'      AND p_desc     THEN b.b_spent        END DESC NULLS LAST,
    CASE WHEN p_sort = 'last_order' AND NOT p_desc THEN b.b_last_order   END ASC  NULLS LAST,
    CASE WHEN p_sort = 'last_order' AND p_desc     THEN b.b_last_order   END DESC NULLS LAST,
    CASE WHEN p_sort NOT IN ('name', 'email', 'orders', 'spent', 'last_order') AND NOT p_desc THEN b.b_joined END ASC NULLS LAST,
    CASE WHEN p_sort NOT IN ('name', 'email', 'orders', 'spent', 'last_order') AND p_desc     THEN b.b_joined END DESC NULLS LAST,
    b.b_id
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 25), 1), 1000)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);
END;
$$;

-- ── 3b. E-mail + last sign-in for a set of profiles ───────────
CREATE OR REPLACE FUNCTION public.admin_profile_emails(p_ids UUID[])
RETURNS TABLE (profile_id UUID, email TEXT, last_sign_in_at TIMESTAMPTZ)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN
    RETURN;
  END IF;
  IF cardinality(p_ids) > 500 THEN
    RAISE EXCEPTION 'too many ids' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT p.id, u.email::text, u.last_sign_in_at
  FROM profiles p
  JOIN auth.users u ON u.id = p.auth_user_id
  WHERE p.id = ANY (p_ids);
END;
$$;

-- ── 3c. Owner only: find an account by e-mail (Team → add) ────
-- Its return columns grow in a later migration (20261114080000), so drop first: re-running stays safe.
DROP FUNCTION IF EXISTS public.admin_profile_by_email(TEXT);
CREATE OR REPLACE FUNCTION public.admin_profile_by_email(p_email TEXT)
RETURNS TABLE (profile_id UUID, full_name TEXT, role TEXT)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'owner access required' USING ERRCODE = '42501';
  END IF;
  IF p_email IS NULL OR length(p_email) > 254 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT p.id, p.full_name, p.role::text
  FROM auth.users u
  JOIN profiles p ON p.auth_user_id = u.id
  WHERE lower(u.email) = lower(btrim(p_email))
  LIMIT 1;
END;
$$;

-- ── 4a. The store always keeps one owner ──────────────────────
CREATE OR REPLACE FUNCTION public.guard_last_owner()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF OLD.role::text = 'super_admin'
     AND (TG_OP = 'DELETE'
          OR NEW.role::text IS DISTINCT FROM 'super_admin'
          OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id) THEN
    -- Serialise owner changes so two owners can't demote each other at once.
    PERFORM pg_advisory_xact_lock(hashtext('shiftsouq.store_owner'));
    IF NOT EXISTS (
      SELECT 1 FROM profiles
      WHERE role::text = 'super_admin' AND auth_user_id IS NOT NULL AND id <> OLD.id
    ) THEN
      RAISE EXCEPTION 'The store must keep at least one owner' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_profiles_last_owner ON profiles;
CREATE TRIGGER trg_profiles_last_owner
  BEFORE UPDATE OF role, auth_user_id OR DELETE ON profiles
  FOR EACH ROW EXECUTE FUNCTION public.guard_last_owner();

-- ── 4b. Transfer ownership (owner → an admin) ─────────────────
-- SECURITY INVOKER: runs as the owner, so row-level security and the
-- role guard (only is_super_admin() may change roles) still apply.
-- Both rows change in one transaction; the old owner becomes an admin.
CREATE OR REPLACE FUNCTION public.transfer_store_ownership(p_target UUID)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  me UUID;
  target_role TEXT;
  target_auth UUID;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'owner access required' USING ERRCODE = '42501';
  END IF;
  SELECT id INTO me FROM profiles WHERE auth_user_id = auth.uid();
  IF me IS NULL OR p_target IS NULL OR p_target = me THEN
    RAISE EXCEPTION 'choose another team member' USING ERRCODE = '22023';
  END IF;

  SELECT role::text, auth_user_id INTO target_role, target_auth FROM profiles WHERE id = p_target FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'team member not found' USING ERRCODE = 'P0002';
  END IF;
  IF target_role <> 'admin' OR target_auth IS NULL THEN
    RAISE EXCEPTION 'ownership can only go to an admin who can sign in' USING ERRCODE = '22023';
  END IF;

  UPDATE profiles SET role = 'super_admin' WHERE id = p_target;
  UPDATE profiles SET role = 'admin' WHERE id = me;
END;
$$;

-- ── Grants: signed-in callers only (each function checks the role) ─
REVOKE ALL ON FUNCTION public.admin_period_stats(TIMESTAMPTZ, TIMESTAMPTZ) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_daily_revenue(INT, TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_top_products(TIMESTAMPTZ, TIMESTAMPTZ, INT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_queue_counts() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_customers(TEXT, TEXT, TEXT, BOOLEAN, INT, INT, UUID) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_profile_emails(UUID[]) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_profile_by_email(TEXT) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.transfer_store_ownership(UUID) FROM PUBLIC, anon;

GRANT EXECUTE ON FUNCTION public.admin_period_stats(TIMESTAMPTZ, TIMESTAMPTZ) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_daily_revenue(INT, TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_top_products(TIMESTAMPTZ, TIMESTAMPTZ, INT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_queue_counts() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_customers(TEXT, TEXT, TEXT, BOOLEAN, INT, INT, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_profile_emails(UUID[]) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_profile_by_email(TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.transfer_store_ownership(UUID) TO authenticated, service_role;

-- ── 5. Indexes for the admin lists ────────────────────────────
CREATE INDEX IF NOT EXISTS idx_orders_created       ON orders (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_user_created  ON orders (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_profiles_role        ON profiles (role, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reviews_status       ON reviews (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_log_actor      ON audit_log (actor_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_newsletter_created   ON newsletter_subscribers (created_at DESC);

-- ════ 20261114050000_admin_catalog.sql ════
-- ══════════════════════════════════════════════════════════════
-- ShiftSouq — admin catalogue management (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- Idempotent (ON CONFLICT / OR REPLACE / DROP … IF EXISTS).
-- Run after 20261114010100_store_platform.sql.
--
-- 1. Storage: public bucket "product-images" (8 MB, jpeg/png/webp/
--    avif). Anyone may read; only admins may upload, replace or
--    delete. Uploads use a signed upload URL created on the server
--    after the admin check, so no key ever reaches the browser.
-- 2. Read models for the admin screens (admins only):
--    admin_catalog_products  — one row per product with stock totals
--    admin_catalog_variants  — one row per variant with its product
-- 3. admin_save_product(jsonb): saves a product, its variants and its
--    images in ONE transaction. A failure halfway leaves nothing
--    half-saved. Variants are updated in place (order history stays
--    linked); a variant with open orders is never deleted; a stored
--    Arabic colour name is never wiped; stock the admin did not touch
--    is never overwritten (so sales made meanwhile are kept).
-- 4. admin_set_category_order / admin_set_collection_products:
--    reordering in one statement.
-- All functions run with the caller's rights (SECURITY INVOKER), so
-- row-level security applies, and refuse non-admins outright.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Storage bucket + policies ──────────────────────────────
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('product-images', 'product-images', true, 8388608,
        ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/avif'])
ON CONFLICT (id) DO UPDATE SET
  public = EXCLUDED.public,
  file_size_limit = EXCLUDED.file_size_limit,
  allowed_mime_types = EXCLUDED.allowed_mime_types;

DROP POLICY IF EXISTS "product_images_public_read" ON storage.objects;
CREATE POLICY "product_images_public_read" ON storage.objects FOR SELECT
  USING (bucket_id = 'product-images');

DROP POLICY IF EXISTS "product_images_admin_insert" ON storage.objects;
CREATE POLICY "product_images_admin_insert" ON storage.objects FOR INSERT
  WITH CHECK (bucket_id = 'product-images' AND public.is_admin());

DROP POLICY IF EXISTS "product_images_admin_update" ON storage.objects;
CREATE POLICY "product_images_admin_update" ON storage.objects FOR UPDATE
  USING (bucket_id = 'product-images' AND public.is_admin())
  WITH CHECK (bucket_id = 'product-images' AND public.is_admin());

DROP POLICY IF EXISTS "product_images_admin_delete" ON storage.objects;
CREATE POLICY "product_images_admin_delete" ON storage.objects FOR DELETE
  USING (bucket_id = 'product-images' AND public.is_admin());

-- ── 2. Read models (admins only) ──────────────────────────────
CREATE INDEX IF NOT EXISTS idx_variants_stock ON product_variants (stock);
CREATE INDEX IF NOT EXISTS idx_products_updated ON products (updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_collection_products_product ON collection_products (product_id);

CREATE OR REPLACE VIEW public.admin_catalog_products
WITH (security_invoker = true) AS
SELECT
  p.id,
  p.slug,
  p.name_en,
  p.name_ar,
  p.category_id,
  c.name_en AS category_name_en,
  c.name_ar AS category_name_ar,
  p.base_price,
  p.sale_price,
  p.is_active,
  p.is_featured,
  p.is_new,
  p.created_at,
  p.updated_at,
  (SELECT i.url FROM product_images i
    WHERE i.product_id = p.id
    ORDER BY i.is_primary DESC NULLS LAST, i.sort_order, i.created_at
    LIMIT 1) AS thumbnail_url,
  COALESCE(s.total_stock, 0)::int AS total_stock,
  COALESCE(s.variant_count, 0)::int AS variant_count,
  COALESCE(s.min_stock, 0)::int AS min_stock,
  COALESCE(s.skus, '') AS skus
FROM products p
LEFT JOIN categories c ON c.id = p.category_id
LEFT JOIN LATERAL (
  SELECT sum(v.stock) AS total_stock, count(*) AS variant_count, min(v.stock) AS min_stock,
         string_agg(v.sku, ' ') AS skus
  FROM product_variants v WHERE v.product_id = p.id
) s ON true
WHERE public.is_admin();

CREATE OR REPLACE VIEW public.admin_catalog_variants
WITH (security_invoker = true) AS
SELECT
  v.id,
  v.product_id,
  v.sku,
  v.size,
  v.color_en,
  v.color_ar,
  v.color_hex,
  COALESCE(v.stock, 0) AS stock,
  v.price_override,
  v.position,
  v.created_at,
  p.name_en AS product_name_en,
  p.name_ar AS product_name_ar,
  p.slug AS product_slug,
  p.is_active AS product_active,
  p.category_id,
  p.base_price,
  p.sale_price,
  COALESCE(
    (SELECT i.url FROM product_images i
      WHERE i.product_id = p.id AND v.color_en IS NOT NULL AND lower(i.color_en) = lower(v.color_en)
      ORDER BY i.sort_order, i.created_at LIMIT 1),
    (SELECT i.url FROM product_images i
      WHERE i.product_id = p.id
      ORDER BY i.is_primary DESC NULLS LAST, i.sort_order, i.created_at LIMIT 1)
  ) AS thumbnail_url
FROM product_variants v
JOIN products p ON p.id = v.product_id
WHERE public.is_admin();

REVOKE ALL ON public.admin_catalog_products FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.admin_catalog_variants FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.admin_catalog_products TO authenticated;
GRANT SELECT ON public.admin_catalog_variants TO authenticated;

-- ── 3. Save a product with its variants and images ────────────
-- Payload (validated on the server first):
-- {
--   "id": uuid | null,                       -- null = new product
--   "expected_updated_at": timestamptz|null, -- refuse if someone saved meanwhile
--   "product":  { name_en, name_ar, slug, category_id, brand, tags[], description_en, description_ar,
--                 details_en, details_ar, care_en, care_ar, base_price, sale_price, size_system,
--                 seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
--                 is_active, is_featured, is_new },
--   "variants": [ { id|null, sku, size, color_en, color_ar, color_hex, stock, stock_loaded|null,
--                   price_override, position } ],
--   "images":   [ { id|null, url, color_en, alt_text_en, alt_text_ar, sort_order, is_primary } ]
-- }
-- Returns { "id", "slug", "removed_image_urls": [...] }.
-- Errors are raised with a short key as the message (P0001):
--   not_found, changed, variant_has_open_orders, stock_changed, duplicate_slug, duplicate_sku, category
CREATE OR REPLACE FUNCTION public.admin_save_product(p_payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
DECLARE
  v_id        uuid := NULLIF(p_payload->>'id', '')::uuid;
  v_p         jsonb := COALESCE(p_payload->'product', '{}'::jsonb);
  v_expected  timestamptz := NULLIF(p_payload->>'expected_updated_at', '')::timestamptz;
  v_slug      text;
  v_current   timestamptz;
  v_keep_var  uuid[];
  v_drop_var  uuid[];
  v_keep_img  uuid[];
  v_removed   text[];
  v_row       jsonb;
  v_vid       uuid;
  v_old       product_variants%ROWTYPE;
  v_stock     int;
  v_loaded    int;
  v_constraint text;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;

  BEGIN
    -- Product row
    IF v_id IS NULL THEN
      INSERT INTO products (
        name_en, name_ar, slug, category_id, brand, tags,
        description_en, description_ar, details_en, details_ar, care_en, care_ar,
        base_price, sale_price, size_system,
        seo_title_en, seo_title_ar, seo_description_en, seo_description_ar,
        is_active, is_featured, is_new
      ) VALUES (
        v_p->>'name_en', v_p->>'name_ar', v_p->>'slug', (v_p->>'category_id')::uuid, NULLIF(v_p->>'brand', ''),
        COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_p->'tags', '[]'::jsonb))), '{}'),
        NULLIF(v_p->>'description_en', ''), NULLIF(v_p->>'description_ar', ''),
        NULLIF(v_p->>'details_en', ''), NULLIF(v_p->>'details_ar', ''),
        NULLIF(v_p->>'care_en', ''), NULLIF(v_p->>'care_ar', ''),
        (v_p->>'base_price')::numeric, NULLIF(v_p->>'sale_price', '')::numeric,
        COALESCE(NULLIF(v_p->>'size_system', ''), 'apparel'),
        NULLIF(v_p->>'seo_title_en', ''), NULLIF(v_p->>'seo_title_ar', ''),
        NULLIF(v_p->>'seo_description_en', ''), NULLIF(v_p->>'seo_description_ar', ''),
        COALESCE((v_p->>'is_active')::boolean, false),
        COALESCE((v_p->>'is_featured')::boolean, false),
        COALESCE((v_p->>'is_new')::boolean, false)
      )
      RETURNING id, slug INTO v_id, v_slug;
    ELSE
      SELECT updated_at INTO v_current FROM products WHERE id = v_id FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0001';
      END IF;
      IF v_expected IS NOT NULL AND v_current IS DISTINCT FROM v_expected THEN
        RAISE EXCEPTION 'changed' USING ERRCODE = 'P0001';
      END IF;

      UPDATE products SET
        name_en = v_p->>'name_en',
        name_ar = v_p->>'name_ar',
        slug = v_p->>'slug',
        category_id = (v_p->>'category_id')::uuid,
        brand = NULLIF(v_p->>'brand', ''),
        tags = COALESCE(ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_p->'tags', '[]'::jsonb))), '{}'),
        description_en = NULLIF(v_p->>'description_en', ''),
        description_ar = NULLIF(v_p->>'description_ar', ''),
        details_en = NULLIF(v_p->>'details_en', ''),
        details_ar = NULLIF(v_p->>'details_ar', ''),
        care_en = NULLIF(v_p->>'care_en', ''),
        care_ar = NULLIF(v_p->>'care_ar', ''),
        base_price = (v_p->>'base_price')::numeric,
        sale_price = NULLIF(v_p->>'sale_price', '')::numeric,
        size_system = COALESCE(NULLIF(v_p->>'size_system', ''), 'apparel'),
        seo_title_en = NULLIF(v_p->>'seo_title_en', ''),
        seo_title_ar = NULLIF(v_p->>'seo_title_ar', ''),
        seo_description_en = NULLIF(v_p->>'seo_description_en', ''),
        seo_description_ar = NULLIF(v_p->>'seo_description_ar', ''),
        is_active = COALESCE((v_p->>'is_active')::boolean, is_active),
        is_featured = COALESCE((v_p->>'is_featured')::boolean, is_featured),
        is_new = COALESCE((v_p->>'is_new')::boolean, is_new)
      WHERE id = v_id
      RETURNING slug INTO v_slug;
    END IF;

    -- Variants: which existing ones stay, which go
    SELECT COALESCE(array_agg(pv.id), '{}') INTO v_keep_var
    FROM product_variants pv
    WHERE pv.product_id = v_id
      AND pv.id IN (
        SELECT NULLIF(e->>'id', '')::uuid FROM jsonb_array_elements(COALESCE(p_payload->'variants', '[]'::jsonb)) e
      );

    SELECT COALESCE(array_agg(pv.id), '{}') INTO v_drop_var
    FROM product_variants pv
    WHERE pv.product_id = v_id AND NOT (pv.id = ANY (v_keep_var));

    IF cardinality(v_drop_var) > 0 THEN
      IF EXISTS (
        SELECT 1 FROM order_items oi JOIN orders o ON o.id = oi.order_id
        WHERE oi.product_variant_id = ANY (v_drop_var)
          AND o.status::text IN ('pending', 'confirmed', 'processing', 'shipped')
      ) THEN
        RAISE EXCEPTION 'variant_has_open_orders' USING ERRCODE = 'P0001';
      END IF;
      DELETE FROM product_variants WHERE id = ANY (v_drop_var);
    END IF;

    -- Park the SKUs of kept variants so two variants can swap SKUs.
    UPDATE product_variants SET sku = '~' || id::text WHERE id = ANY (v_keep_var);

    FOR v_row IN SELECT * FROM jsonb_array_elements(COALESCE(p_payload->'variants', '[]'::jsonb))
    LOOP
      v_vid := NULLIF(v_row->>'id', '')::uuid;
      v_stock := GREATEST(COALESCE((v_row->>'stock')::int, 0), 0);
      IF v_vid IS NOT NULL AND v_vid = ANY (v_keep_var) THEN
        SELECT * INTO v_old FROM product_variants WHERE id = v_vid FOR UPDATE;
        v_loaded := NULLIF(v_row->>'stock_loaded', '')::int;
        -- Stock: only written when the admin changed it; refused if it moved meanwhile.
        IF v_loaded IS NOT NULL AND v_stock <> v_loaded AND COALESCE(v_old.stock, 0) <> v_loaded THEN
          RAISE EXCEPTION 'stock_changed' USING ERRCODE = 'P0001';
        END IF;
        UPDATE product_variants SET
          sku = v_row->>'sku',
          size = NULLIF(v_row->>'size', ''),
          color_en = NULLIF(v_row->>'color_en', ''),
          -- Never wipe a stored Arabic colour name with a blank.
          color_ar = COALESCE(NULLIF(v_row->>'color_ar', ''), CASE WHEN NULLIF(v_row->>'color_en', '') IS NULL THEN NULL ELSE v_old.color_ar END),
          color_hex = COALESCE(NULLIF(v_row->>'color_hex', ''), CASE WHEN NULLIF(v_row->>'color_en', '') IS NULL THEN NULL ELSE v_old.color_hex END),
          stock = CASE WHEN v_loaded IS NOT NULL AND v_stock = v_loaded THEN stock ELSE v_stock END,
          price_override = NULLIF(v_row->>'price_override', '')::numeric,
          position = COALESCE((v_row->>'position')::int, 0)
        WHERE id = v_vid;
      ELSE
        INSERT INTO product_variants (product_id, sku, size, color_en, color_ar, color_hex, stock, price_override, position)
        VALUES (
          v_id, v_row->>'sku', NULLIF(v_row->>'size', ''), NULLIF(v_row->>'color_en', ''),
          NULLIF(v_row->>'color_ar', ''), NULLIF(v_row->>'color_hex', ''), v_stock,
          NULLIF(v_row->>'price_override', '')::numeric, COALESCE((v_row->>'position')::int, 0)
        );
      END IF;
    END LOOP;

    -- Images
    SELECT COALESCE(array_agg(pi.id), '{}') INTO v_keep_img
    FROM product_images pi
    WHERE pi.product_id = v_id
      AND pi.id IN (
        SELECT NULLIF(e->>'id', '')::uuid FROM jsonb_array_elements(COALESCE(p_payload->'images', '[]'::jsonb)) e
      );

    WITH gone AS (
      DELETE FROM product_images WHERE product_id = v_id AND NOT (id = ANY (v_keep_img)) RETURNING url
    )
    SELECT COALESCE(array_agg(url), '{}') INTO v_removed FROM gone;

    FOR v_row IN SELECT * FROM jsonb_array_elements(COALESCE(p_payload->'images', '[]'::jsonb))
    LOOP
      v_vid := NULLIF(v_row->>'id', '')::uuid;
      IF v_vid IS NOT NULL AND v_vid = ANY (v_keep_img) THEN
        UPDATE product_images SET
          url = v_row->>'url',
          color_en = NULLIF(v_row->>'color_en', ''),
          alt_text_en = NULLIF(v_row->>'alt_text_en', ''),
          alt_text_ar = NULLIF(v_row->>'alt_text_ar', ''),
          sort_order = COALESCE((v_row->>'sort_order')::int, 0),
          is_primary = COALESCE((v_row->>'is_primary')::boolean, false)
        WHERE id = v_vid;
      ELSE
        INSERT INTO product_images (product_id, url, color_en, alt_text_en, alt_text_ar, sort_order, is_primary)
        VALUES (
          v_id, v_row->>'url', NULLIF(v_row->>'color_en', ''), NULLIF(v_row->>'alt_text_en', ''),
          NULLIF(v_row->>'alt_text_ar', ''), COALESCE((v_row->>'sort_order')::int, 0),
          COALESCE((v_row->>'is_primary')::boolean, false)
        );
      END IF;
    END LOOP;

    -- Exactly one primary image (the first one when none was chosen).
    IF EXISTS (SELECT 1 FROM product_images WHERE product_id = v_id)
       AND (SELECT count(*) FROM product_images WHERE product_id = v_id AND is_primary) <> 1 THEN
      UPDATE product_images SET is_primary = (id = (
        SELECT id FROM product_images WHERE product_id = v_id
        ORDER BY is_primary DESC NULLS LAST, sort_order, created_at LIMIT 1
      ))
      WHERE product_id = v_id;
    END IF;

  EXCEPTION
    WHEN unique_violation THEN
      GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
      RAISE EXCEPTION '%', CASE
        WHEN v_constraint = 'products_slug_key' THEN 'duplicate_slug'
        WHEN v_constraint = 'product_variants_sku_key' THEN 'duplicate_sku'
        ELSE 'duplicate' END
      USING ERRCODE = 'P0001';
    WHEN foreign_key_violation THEN
      RAISE EXCEPTION 'category' USING ERRCODE = 'P0001';
  END;

  RETURN jsonb_build_object('id', v_id, 'slug', v_slug, 'removed_image_urls', to_jsonb(v_removed));
END;
$$;

-- ── 4. Reordering helpers ─────────────────────────────────────
-- Sets sort_order = position in the list (1-based) for the given categories.
CREATE OR REPLACE FUNCTION public.admin_set_category_order(p_ids uuid[])
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  UPDATE categories c SET sort_order = o.pos
  FROM unnest(p_ids) WITH ORDINALITY AS o(id, pos)
  WHERE c.id = o.id;
END;
$$;

-- Replaces a collection's products with the given list, in that order.
CREATE OR REPLACE FUNCTION public.admin_set_collection_products(p_collection uuid, p_products uuid[])
RETURNS void
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'admin access required' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM collections WHERE id = p_collection) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0001';
  END IF;
  DELETE FROM collection_products WHERE collection_id = p_collection AND NOT (product_id = ANY (p_products));
  INSERT INTO collection_products (collection_id, product_id, position)
  SELECT p_collection, o.id, o.pos::int
  FROM unnest(p_products) WITH ORDINALITY AS o(id, pos)
  JOIN products p ON p.id = o.id
  ON CONFLICT (collection_id, product_id) DO UPDATE SET position = EXCLUDED.position;
END;
$$;

REVOKE ALL ON FUNCTION public.admin_save_product(jsonb) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_set_category_order(uuid[]) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_set_collection_products(uuid, uuid[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_save_product(jsonb) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_set_category_order(uuid[]) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.admin_set_collection_products(uuid, uuid[]) TO authenticated, service_role;

-- ════ 20261114060000_orders_i18n_promo.sql ════
-- ══════════════════════════════════════════════════════════════
-- Orders: Arabic item names, and promo uses returned on cancel.
-- Idempotent.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Arabic product name / variant label on order lines ─────
-- place_order() stores the English name; this trigger adds the
-- Arabic one from the catalogue at the moment of purchase, so
-- receipts stay correct even if the product is renamed later.
ALTER TABLE order_items ADD COLUMN IF NOT EXISTS product_name_ar TEXT;
ALTER TABLE order_items ADD COLUMN IF NOT EXISTS variant_label_ar TEXT;

CREATE OR REPLACE FUNCTION public.fill_order_item_arabic()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_name_ar TEXT;
  v_size    TEXT;
  v_color   TEXT;
BEGIN
  IF NEW.product_variant_id IS NOT NULL AND (NEW.product_name_ar IS NULL OR NEW.variant_label_ar IS NULL) THEN
    SELECT p.name_ar, v.size, COALESCE(v.color_ar, v.color_en)
      INTO v_name_ar, v_size, v_color
      FROM product_variants v JOIN products p ON p.id = v.product_id
     WHERE v.id = NEW.product_variant_id;
    NEW.product_name_ar  := COALESCE(NEW.product_name_ar, v_name_ar);
    NEW.variant_label_ar := COALESCE(NEW.variant_label_ar, NULLIF(concat_ws(' / ', v_size, v_color), ''));
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_order_items_arabic ON order_items;
CREATE TRIGGER trg_order_items_arabic BEFORE INSERT ON order_items
  FOR EACH ROW EXECUTE FUNCTION public.fill_order_item_arabic();

-- Backfill existing lines (only where the variant still exists).
UPDATE order_items oi
   SET product_name_ar  = COALESCE(oi.product_name_ar, p.name_ar),
       variant_label_ar = COALESCE(oi.variant_label_ar, NULLIF(concat_ws(' / ', v.size, COALESCE(v.color_ar, v.color_en)), ''))
  FROM product_variants v JOIN products p ON p.id = v.product_id
 WHERE v.id = oi.product_variant_id
   AND (oi.product_name_ar IS NULL OR oi.variant_label_ar IS NULL);

-- ── 2. Give the promo use back when an order is cancelled ─────
ALTER TABLE orders ADD COLUMN IF NOT EXISTS promo_released BOOLEAN NOT NULL DEFAULT false;

CREATE OR REPLACE FUNCTION public.release_promo_on_cancel()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM NEW.status
     AND NEW.promocode_id IS NOT NULL AND NOT NEW.promo_released THEN
    UPDATE promocodes SET current_uses = GREATEST(COALESCE(current_uses, 0) - 1, 0) WHERE id = NEW.promocode_id;
    NEW.promo_released := true;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_orders_release_promo ON orders;
CREATE TRIGGER trg_orders_release_promo BEFORE UPDATE OF status ON orders
  FOR EACH ROW EXECUTE FUNCTION public.release_promo_on_cancel();

REVOKE ALL ON FUNCTION public.fill_order_item_arabic() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.release_promo_on_cancel() FROM PUBLIC, anon, authenticated;

-- ════ 20261114070000_checkout.sql ════
-- ══════════════════════════════════════════════════════════════
-- Checkout: rate limits for guest-facing lookups (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- Idempotent. Guests can now check out, try promo codes and track
-- an order by number + email. Those endpoints are limited per
-- client (hashed IP) and per target so codes and orders can't be
-- guessed. Fixed windows, counted in one row per key.
--
-- Only the server (service role) may call rate_limit_hit(); the
-- table has RLS on and no policies, so the browser can't read it.
-- ══════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.rate_limits (
  key          TEXT PRIMARY KEY CHECK (char_length(key) <= 200),
  window_start TIMESTAMPTZ NOT NULL DEFAULT now(),
  hits         INT NOT NULL DEFAULT 0
);

ALTER TABLE public.rate_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.rate_limits FROM anon, authenticated;

-- Adds p_cost hits to p_key's current window and says whether the
-- call is allowed: true while the window had room before this call.
-- p_cost = 0 only checks (nothing is counted).
CREATE OR REPLACE FUNCTION public.rate_limit_hit(
  p_key            TEXT,
  p_limit          INT,
  p_window_seconds INT,
  p_cost           INT DEFAULT 1
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_hits INT;
  v_cost INT := GREATEST(COALESCE(p_cost, 1), 0);
BEGIN
  IF p_key IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_window_seconds IS NULL OR p_window_seconds < 1 THEN
    RAISE EXCEPTION 'invalid_rate_limit' USING ERRCODE = '22023';
  END IF;

  INSERT INTO rate_limits AS r (key, window_start, hits)
  VALUES (left(p_key, 200), now(), v_cost)
  ON CONFLICT (key) DO UPDATE SET
    hits = CASE WHEN r.window_start <= now() - make_interval(secs => p_window_seconds)
                THEN v_cost ELSE r.hits + v_cost END,
    window_start = CASE WHEN r.window_start <= now() - make_interval(secs => p_window_seconds)
                        THEN now() ELSE r.window_start END
  RETURNING hits INTO v_hits;

  -- Housekeeping: now and then, forget windows older than a day.
  IF random() < 0.02 THEN
    DELETE FROM rate_limits WHERE window_start < now() - interval '1 day';
  END IF;

  RETURN v_hits - v_cost < p_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.rate_limit_hit(TEXT, INT, INT, INT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rate_limit_hit(TEXT, INT, INT, INT) TO service_role;

-- ════ 20261114080000_security_fixes.sql ════
-- ══════════════════════════════════════════════════════════════
-- ShiftSouq — security review fixes (2026-11-14)
-- ──────────────────────────────────────────────────────────────
-- Idempotent and safe on a database that already has orders.
--
--  1. payment_attempts: every Paymob order we register is recorded
--     with its order and amount. The payment webhook finds the
--     order from Paymob's SIGNED order id, never from the unsigned
--     merchant_order_id.
--  2. mark_order_paid(order, paymob order, amount, transaction,
--     success): refuses attempts that don't belong to the order,
--     one transaction id can confirm one order only, a payment that
--     arrives after the order was cancelled revives it only when
--     every item (and the promo code) can be taken again; otherwise
--     the payment is recorded and the order is flagged needs_refund.
--     Remarks go to audit_log (entity 'payment'), not orders.notes.
--  3. place_order(): at most 20 lines and 10 of each item, the
--     variant must belong to the product sent, an optional cash on
--     delivery ceiling (p_cod_max) and an optional cap on open
--     unpaid orders per phone / email (p_max_open_orders).
--  4. order_internal_notes: staff notes live in their own table
--     (admins only). orders.notes is the buyer's delivery note.
--  5. profiles: staff may read and update (not delete) profiles,
--     and may not edit other team members; only the owner deletes.
--     Deleting a profile keeps its orders (user_id becomes NULL).
--  6. admin_profile_by_email() also returns email_confirmed_at and
--     last_sign_in_at (the owner can't promote unconfirmed accounts).
--  7. rate_limit_hit(): a negative cost gives hits back (refund).
--  8. contact_messages: no direct inserts with the public key.
--  9. reviews: the public key can read only the public columns
--     (not user_id).
-- ══════════════════════════════════════════════════════════════

-- ── 1. Payment attempts ───────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.payment_attempts (
  paymob_order_id TEXT PRIMARY KEY CHECK (char_length(paymob_order_id) BETWEEN 1 AND 100),
  order_id        UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  amount_cents    BIGINT NOT NULL CHECK (amount_cents > 0),
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_payment_attempts_order ON public.payment_attempts(order_id, created_at DESC);

-- Server only: RLS on, no policies, no grants for the public roles.
ALTER TABLE public.payment_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.payment_attempts FROM anon, authenticated;

-- Payments started before this migration: their (latest) Paymob order is on the order row.
INSERT INTO public.payment_attempts (paymob_order_id, order_id, amount_cents, created_at)
SELECT o.paymob_order_id, o.id, ROUND(o.total * 100)::bigint, COALESCE(o.updated_at, o.created_at, now())
  FROM public.orders o
 WHERE o.paymob_order_id IS NOT NULL
   AND btrim(o.paymob_order_id) <> ''
   AND char_length(o.paymob_order_id) <= 100
   AND o.total > 0
ON CONFLICT (paymob_order_id) DO NOTHING;

-- Between running this migration and deploying the new app, the previous
-- app registers Paymob orders by writing orders.paymob_order_id only. Turn
-- those into attempts too, so their payments can still be confirmed. (The
-- new app records the attempt first; this then changes nothing.)
CREATE OR REPLACE FUNCTION public.record_paymob_attempt()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.paymob_order_id IS NOT NULL AND btrim(NEW.paymob_order_id) <> ''
     AND char_length(NEW.paymob_order_id) <= 100
     AND NEW.paymob_order_id IS DISTINCT FROM OLD.paymob_order_id
     AND NEW.total > 0 THEN
    INSERT INTO payment_attempts (paymob_order_id, order_id, amount_cents)
    VALUES (NEW.paymob_order_id, NEW.id, ROUND(NEW.total * 100)::bigint)
    ON CONFLICT (paymob_order_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_orders_paymob_attempt ON public.orders;
CREATE TRIGGER trg_orders_paymob_attempt AFTER UPDATE OF paymob_order_id ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.record_paymob_attempt();
REVOKE ALL ON FUNCTION public.record_paymob_attempt() FROM PUBLIC, anon, authenticated;

-- ── 2. Orders: refund flag, one transaction per paid order ────
ALTER TABLE public.orders ADD COLUMN IF NOT EXISTS needs_refund BOOLEAN NOT NULL DEFAULT false;

-- Paid orders that share a transaction id (only possible through the old
-- webhook): the earliest keeps it, the others get a suffix and an audit
-- entry so the owner can check them with Paymob.
WITH dup AS (
  SELECT id, transaction_id,
         row_number() OVER (PARTITION BY transaction_id ORDER BY created_at, id) AS rn
    FROM public.orders
   WHERE payment_status = 'paid' AND transaction_id IS NOT NULL
), renamed AS (
  UPDATE public.orders o
     SET transaction_id = dup.transaction_id || ' (duplicate ' || o.order_number || ')'
    FROM dup
   WHERE dup.id = o.id AND dup.rn > 1
  RETURNING o.id, dup.transaction_id AS original
)
INSERT INTO public.audit_log (actor_id, action, entity, entity_id, data)
SELECT NULL, 'payment.duplicate_transaction', 'payment', renamed.id::text,
       jsonb_build_object('transaction_id', renamed.original,
                          'remark', 'This transaction id had already confirmed another order. Check the payment with Paymob.')
  FROM renamed;

CREATE UNIQUE INDEX IF NOT EXISTS uq_orders_paid_transaction
  ON public.orders(transaction_id)
  WHERE payment_status = 'paid' AND transaction_id IS NOT NULL;

-- Open unpaid orders per phone / email (place_order's cap).
CREATE INDEX IF NOT EXISTS idx_orders_open_phone ON public.orders(shipping_phone)
  WHERE status = 'pending' AND payment_status IN ('unpaid', 'failed');
CREATE INDEX IF NOT EXISTS idx_orders_open_email ON public.orders(lower(shipping_email))
  WHERE status = 'pending' AND payment_status IN ('unpaid', 'failed');

-- ── 3. Internal staff notes ───────────────────────────────────
CREATE TABLE IF NOT EXISTS public.order_internal_notes (
  order_id   UUID PRIMARY KEY REFERENCES public.orders(id) ON DELETE CASCADE,
  note       TEXT NOT NULL DEFAULT '' CHECK (char_length(note) <= 2000),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL
);

ALTER TABLE public.order_internal_notes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.order_internal_notes FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.order_internal_notes TO authenticated;
DROP POLICY IF EXISTS admin_order_internal_notes ON public.order_internal_notes;
CREATE POLICY admin_order_internal_notes ON public.order_internal_notes
  FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());

-- Notes the team edited (audited 'order.note') move to the internal note;
-- the order keeps no staff text. Orders that already have an internal note
-- are left alone, so this runs once per order.
WITH moved AS (
  INSERT INTO public.order_internal_notes (order_id, note, updated_at, updated_by)
  SELECT o.id,
         left(o.notes, 2000),
         now(),
         (SELECT a.actor_id FROM public.audit_log a
           WHERE a.action = 'order.note' AND a.entity = 'orders' AND a.entity_id = o.id::text
           ORDER BY a.created_at DESC LIMIT 1)
    FROM public.orders o
   WHERE o.notes IS NOT NULL AND btrim(o.notes) <> ''
     AND EXISTS (SELECT 1 FROM public.audit_log a
                  WHERE a.action = 'order.note' AND a.entity = 'orders' AND a.entity_id = o.id::text)
     AND NOT EXISTS (SELECT 1 FROM public.order_internal_notes n WHERE n.order_id = o.id)
  ON CONFLICT (order_id) DO NOTHING
  RETURNING order_id
)
UPDATE public.orders o SET notes = NULL FROM moved WHERE o.id = moved.order_id;

-- Payment remarks the old webhook appended to orders.notes.
WITH m AS (
  SELECT id,
         array_to_string(ARRAY(
           SELECT r[1] FROM regexp_matches(notes, '(Amount mismatch: paid \d+ cents, expected \d+)', 'g') AS r
         ), E'\n') AS remarks
    FROM public.orders
   WHERE notes ~ 'Amount mismatch: paid \d+ cents, expected \d+'
), kept AS (
  INSERT INTO public.order_internal_notes AS n (order_id, note)
  SELECT m.id, left(m.remarks, 2000) FROM m
  ON CONFLICT (order_id) DO UPDATE
    SET note = left(concat_ws(E'\n', NULLIF(n.note, ''), EXCLUDED.note), 2000)
  RETURNING n.order_id
)
UPDATE public.orders o
   SET notes = NULLIF(btrim(regexp_replace(o.notes, '\n?Amount mismatch: paid \d+ cents, expected \d+', '', 'g'), E' \n'), '')
  FROM kept
 WHERE o.id = kept.order_id;

-- ── 4. place_order(): caps and checks ─────────────────────────
DROP FUNCTION IF EXISTS public.place_order(UUID, JSONB, NUMERIC, TEXT, JSONB, TEXT);

CREATE OR REPLACE FUNCTION public.place_order(
  p_user_id          UUID,
  p_items            JSONB,
  p_shipping_cost    NUMERIC,
  p_payment_method   TEXT,
  p_contact          JSONB,
  p_promo_code       TEXT DEFAULT NULL,
  p_cod_max          NUMERIC DEFAULT NULL,
  p_max_open_orders  INT DEFAULT NULL
)
RETURNS TABLE(order_id UUID, order_number TEXT, total NUMERIC, access_token UUID)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
#variable_conflict use_column
DECLARE
  it         JSONB;
  v          RECORD;
  v_product  UUID;
  v_variant  UUID;
  v_count    INT;
  v_open     INT;
  v_phone    TEXT;
  v_email    TEXT;
  qty        INT;
  price      NUMERIC;
  v_subtotal NUMERIC := 0;
  v_discount NUMERIC := 0;
  v_total    NUMERIC;
  v_promo    promocodes%ROWTYPE;
  v_order    orders%ROWTYPE;
  v_number   TEXT;
  lines      JSONB := '[]'::jsonb;
BEGIN
  IF p_payment_method NOT IN ('cod', 'card', 'wallet') THEN
    RAISE EXCEPTION 'invalid_payment_method' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'empty_cart' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_items) > 20 THEN
    RAISE EXCEPTION 'too_many_items' USING ERRCODE = '22023';
  END IF;
  IF p_shipping_cost IS NULL OR p_shipping_cost < 0 THEN
    RAISE EXCEPTION 'invalid_shipping' USING ERRCODE = '22023';
  END IF;
  -- At most 10 of one item, even when it is sent on several lines.
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_items) e
     GROUP BY COALESCE(NULLIF(e.value ->> 'variant_id', ''), e.value ->> 'product_id')
    HAVING sum((e.value ->> 'quantity')::int) > 10
  ) THEN
    RAISE EXCEPTION 'invalid_quantity' USING ERRCODE = '22023';
  END IF;

  -- Give back stock held by abandoned online orders before checking availability.
  PERFORM public.expire_unpaid_orders();

  -- Open unpaid orders per phone / email (serialised per buyer so two requests can't both pass).
  IF p_max_open_orders IS NOT NULL THEN
    v_phone := NULLIF(btrim(p_contact ->> 'phone'), '');
    v_email := lower(NULLIF(btrim(p_contact ->> 'email'), ''));
    PERFORM pg_advisory_xact_lock(hashtext('shiftsouq.open_orders.phone:' || COALESCE(v_phone, '')));
    PERFORM pg_advisory_xact_lock(hashtext('shiftsouq.open_orders.email:' || COALESCE(v_email, '')));
    SELECT count(*) INTO v_open
      FROM orders o
     WHERE o.status = 'pending'
       AND o.payment_status IN ('unpaid', 'failed')
       AND ((v_phone IS NOT NULL AND o.shipping_phone = v_phone)
         OR (v_email IS NOT NULL AND lower(o.shipping_email) = v_email));
    IF v_open >= p_max_open_orders THEN
      RAISE EXCEPTION 'too_many_open_orders' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  -- Price and reserve every line. Rows are locked in a stable order to avoid deadlocks.
  FOR it IN SELECT value FROM jsonb_array_elements(p_items)
             ORDER BY value ->> 'product_id', value ->> 'variant_id'
  LOOP
    qty := (it ->> 'quantity')::int;
    IF qty IS NULL OR qty < 1 OR qty > 10 THEN
      RAISE EXCEPTION 'invalid_quantity' USING ERRCODE = '22023';
    END IF;

    v_product := NULLIF(it ->> 'product_id', '')::uuid;
    IF v_product IS NULL THEN
      RAISE EXCEPTION 'product_unavailable:%', it ->> 'variant_id' USING ERRCODE = 'P0001';
    END IF;

    -- Products without options are added to the cart without a variant: use their only variant.
    v_variant := NULLIF(it ->> 'variant_id', '')::uuid;
    IF v_variant IS NULL THEN
      SELECT count(*), min(id::text)::uuid INTO v_count, v_variant
        FROM product_variants WHERE product_id = v_product;
      IF v_count <> 1 THEN
        RAISE EXCEPTION 'choose_variant:%', v_product USING ERRCODE = 'P0001';
      END IF;
    END IF;

    SELECT pv.id, pv.stock, pv.size, pv.color_en, pv.price_override,
           p.id AS product_id, p.name_en, p.base_price, p.sale_price, p.is_active,
           (SELECT url FROM product_images pi WHERE pi.product_id = p.id
             ORDER BY pi.is_primary DESC, pi.sort_order LIMIT 1) AS image_url
      INTO v
      FROM product_variants pv
      JOIN products p ON p.id = pv.product_id
     WHERE pv.id = v_variant
       FOR UPDATE OF pv;

    -- The variant must exist, be on sale and belong to the product the buyer chose.
    IF NOT FOUND OR NOT v.is_active OR v.product_id <> v_product THEN
      RAISE EXCEPTION 'product_unavailable:%', v_variant USING ERRCODE = 'P0001';
    END IF;
    IF COALESCE(v.stock, 0) < qty THEN
      RAISE EXCEPTION 'out_of_stock:%', v_variant USING ERRCODE = 'P0001';
    END IF;

    price := COALESCE(v.price_override,
                      CASE WHEN v.sale_price IS NOT NULL AND v.sale_price > 0 AND v.sale_price < v.base_price
                           THEN v.sale_price ELSE v.base_price END);

    UPDATE product_variants SET stock = stock - qty WHERE id = v.id;
    v_subtotal := v_subtotal + price * qty;

    lines := lines || jsonb_build_object(
      'variant_id', v.id,
      'name', v.name_en,
      'label', NULLIF(CONCAT_WS(' / ', NULLIF(v.size, ''), NULLIF(v.color_en, '')), ''),
      'price', price,
      'quantity', qty,
      'image', v.image_url
    );
  END LOOP;

  -- Promo code (locked so max_uses can't be exceeded by concurrent orders).
  IF p_promo_code IS NOT NULL AND trim(p_promo_code) <> '' THEN
    SELECT * INTO v_promo FROM promocodes
     WHERE lower(code) = lower(trim(p_promo_code)) FOR UPDATE;
    IF NOT FOUND OR NOT v_promo.is_active
       OR (v_promo.expires_at IS NOT NULL AND v_promo.expires_at <= now())
       OR (v_promo.max_uses IS NOT NULL AND COALESCE(v_promo.current_uses, 0) >= v_promo.max_uses)
       OR v_subtotal < COALESCE(v_promo.min_order_amount, 0) THEN
      RAISE EXCEPTION 'invalid_promo' USING ERRCODE = 'P0001';
    END IF;
    v_discount := LEAST(v_subtotal, ROUND(CASE WHEN v_promo.discount_type = 'percentage'
                                               THEN v_subtotal * v_promo.discount_value / 100
                                               ELSE v_promo.discount_value END, 2));
    UPDATE promocodes SET current_uses = COALESCE(current_uses, 0) + 1 WHERE id = v_promo.id;
  END IF;

  v_total := v_subtotal - v_discount + p_shipping_cost;

  -- Cash on delivery only up to the store's limit (the whole transaction rolls back).
  IF p_payment_method = 'cod' AND p_cod_max IS NOT NULL AND v_total > p_cod_max THEN
    RAISE EXCEPTION 'cod_limit' USING ERRCODE = 'P0001';
  END IF;

  -- Human-readable, collision-checked order number: SS-YYYYMMDD-XXXXXX
  LOOP
    v_number := 'SS-' || to_char(now() AT TIME ZONE 'Africa/Cairo', 'YYYYMMDD') || '-' ||
                upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
    EXIT WHEN NOT EXISTS (SELECT 1 FROM orders o WHERE o.order_number = v_number);
  END LOOP;

  INSERT INTO orders (
    user_id, order_number, status, payment_status, payment_method,
    subtotal, discount_amount, shipping_cost, tax_amount, total, promocode_id,
    shipping_name, shipping_phone, shipping_email, shipping_country,
    shipping_governorate, shipping_city, shipping_address, notes
  ) VALUES (
    p_user_id, v_number, 'pending', 'unpaid', p_payment_method,
    v_subtotal, v_discount, p_shipping_cost, 0, v_total, v_promo.id,
    p_contact ->> 'name', p_contact ->> 'phone', p_contact ->> 'email', 'EG',
    p_contact ->> 'governorate', p_contact ->> 'city', p_contact ->> 'address', p_contact ->> 'notes'
  )
  RETURNING * INTO v_order;

  INSERT INTO order_items (order_id, product_variant_id, product_name, variant_label, unit_price, quantity, image_url)
  SELECT v_order.id, (l ->> 'variant_id')::uuid, l ->> 'name', l ->> 'label',
         (l ->> 'price')::numeric, (l ->> 'quantity')::int, l ->> 'image'
    FROM jsonb_array_elements(lines) AS l;

  RETURN QUERY SELECT v_order.id, v_order.order_number, v_order.total, v_order.access_token;
END;
$$;

REVOKE ALL ON FUNCTION public.place_order(UUID, JSONB, NUMERIC, TEXT, JSONB, TEXT, NUMERIC, INT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.place_order(UUID, JSONB, NUMERIC, TEXT, JSONB, TEXT, NUMERIC, INT) TO service_role;

-- ── 5. mark_order_paid(): tied to a payment attempt ───────────
DROP FUNCTION IF EXISTS public.mark_order_paid(UUID, BIGINT, TEXT, BOOLEAN);

CREATE OR REPLACE FUNCTION public.mark_order_paid(
  p_order_id        UUID,
  p_paymob_order_id TEXT,
  p_amount_cents    BIGINT,
  p_transaction_id  TEXT,
  p_success         BOOLEAN
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
#variable_conflict use_column
DECLARE
  o          orders%ROWTYPE;
  a          payment_attempts%ROWTYPE;
  v_txn      TEXT := NULLIF(btrim(p_transaction_id), '');
  v_expected BIGINT;
  v_promo    promocodes%ROWTYPE;
  v_recount  BOOLEAN := false;
  v_can      BOOLEAN := true;
BEGIN
  -- The attempt (Paymob's signed order id) must have been registered for this order.
  SELECT * INTO a FROM payment_attempts WHERE paymob_order_id = p_paymob_order_id;
  IF NOT FOUND OR a.order_id IS DISTINCT FROM p_order_id THEN
    RETURN 'unknown_attempt';
  END IF;

  SELECT * INTO o FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN 'not_found'; END IF;

  IF o.payment_status = 'paid' THEN
    IF COALESCE(p_success, false) AND v_txn IS DISTINCT FROM o.transaction_id THEN
      -- A second successful payment for a paid order: keep it on record for the owner.
      INSERT INTO audit_log (actor_id, action, entity, entity_id, data)
      VALUES (NULL, 'payment.duplicate', 'payment', o.id::text,
              jsonb_build_object('transaction_id', v_txn, 'paid_with', o.transaction_id,
                                 'amount_cents', p_amount_cents, 'paymob_order_id', p_paymob_order_id));
      RETURN 'already_paid_other';
    END IF;
    RETURN 'already_paid';
  END IF;

  IF NOT COALESCE(p_success, false) THEN
    UPDATE orders SET payment_status = 'failed', transaction_id = v_txn WHERE id = o.id;
    RETURN 'failed';
  END IF;

  IF v_txn IS NULL THEN RETURN 'invalid_transaction'; END IF;

  v_expected := ROUND(o.total * 100);
  IF p_amount_cents IS DISTINCT FROM a.amount_cents OR p_amount_cents IS DISTINCT FROM v_expected THEN
    UPDATE orders SET payment_status = 'failed', transaction_id = v_txn WHERE id = o.id;
    INSERT INTO audit_log (actor_id, action, entity, entity_id, data)
    VALUES (NULL, 'payment.amount_mismatch', 'payment', o.id::text,
            jsonb_build_object('transaction_id', v_txn, 'paid_cents', p_amount_cents,
                               'expected_cents', v_expected, 'paymob_order_id', p_paymob_order_id));
    RETURN 'amount_mismatch';
  END IF;

  -- One transaction confirms one order.
  IF EXISTS (SELECT 1 FROM orders x WHERE x.transaction_id = v_txn AND x.payment_status = 'paid' AND x.id <> o.id) THEN
    INSERT INTO audit_log (actor_id, action, entity, entity_id, data)
    VALUES (NULL, 'payment.transaction_reused', 'payment', o.id::text,
            jsonb_build_object('transaction_id', v_txn, 'paymob_order_id', p_paymob_order_id));
    RETURN 'transaction_reused';
  END IF;

  IF o.status IN ('cancelled', 'refunded') THEN
    -- Paid after the order was cancelled (e.g. its payment window ran out).
    -- Revive it only if every item can be taken from stock again and the
    -- promo code (if its use was given back) still has a use left.
    IF o.status <> 'cancelled' THEN
      v_can := false;
    END IF;

    IF v_can AND o.stock_released THEN
      PERFORM 1 FROM product_variants v
        WHERE v.id IN (SELECT oi.product_variant_id FROM order_items oi WHERE oi.order_id = o.id)
        ORDER BY v.id
        FOR UPDATE;
      IF EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id = o.id AND oi.product_variant_id IS NULL)
         OR EXISTS (
           SELECT 1
             FROM (SELECT oi.product_variant_id AS vid, sum(oi.quantity) AS qty
                     FROM order_items oi WHERE oi.order_id = o.id GROUP BY 1) need
             LEFT JOIN product_variants v ON v.id = need.vid
            WHERE v.id IS NULL OR COALESCE(v.stock, 0) < need.qty) THEN
        v_can := false;
      END IF;
    END IF;

    IF v_can AND o.promocode_id IS NOT NULL AND o.promo_released THEN
      SELECT * INTO v_promo FROM promocodes WHERE id = o.promocode_id FOR UPDATE;
      IF NOT FOUND OR NOT COALESCE(v_promo.is_active, false)
         OR (v_promo.expires_at IS NOT NULL AND v_promo.expires_at <= o.created_at)
         OR (v_promo.max_uses IS NOT NULL AND COALESCE(v_promo.current_uses, 0) >= v_promo.max_uses) THEN
        v_can := false;
      ELSE
        v_recount := true;
      END IF;
    END IF;

    IF NOT v_can THEN
      UPDATE orders SET payment_status = 'paid', transaction_id = v_txn, needs_refund = true WHERE id = o.id;
      INSERT INTO audit_log (actor_id, action, entity, entity_id, data)
      VALUES (NULL, 'payment.paid_after_cancel', 'payment', o.id::text,
              jsonb_build_object('transaction_id', v_txn, 'amount_cents', p_amount_cents, 'revived', false));
      RETURN 'paid_after_cancel';
    END IF;

    IF o.stock_released THEN
      UPDATE product_variants v
         SET stock = v.stock - need.qty
        FROM (SELECT oi.product_variant_id AS vid, sum(oi.quantity) AS qty
                FROM order_items oi WHERE oi.order_id = o.id GROUP BY 1) need
       WHERE v.id = need.vid;
    END IF;
    IF v_recount THEN
      UPDATE promocodes SET current_uses = COALESCE(current_uses, 0) + 1 WHERE id = v_promo.id;
    END IF;
    UPDATE orders
       SET payment_status = 'paid', transaction_id = v_txn, status = 'confirmed',
           stock_released = false, promo_released = CASE WHEN v_recount THEN false ELSE promo_released END,
           needs_refund = false
     WHERE id = o.id;
    INSERT INTO audit_log (actor_id, action, entity, entity_id, data)
    VALUES (NULL, 'payment.paid_after_cancel', 'payment', o.id::text,
            jsonb_build_object('transaction_id', v_txn, 'amount_cents', p_amount_cents, 'revived', true));
    RETURN 'paid';
  END IF;

  -- Orders placed before stock was reserved at checkout: take it now.
  IF o.stock_released THEN
    UPDATE product_variants v SET stock = GREATEST(0, v.stock - oi.quantity)
      FROM order_items oi WHERE oi.order_id = o.id AND oi.product_variant_id = v.id;
    UPDATE orders SET stock_released = false WHERE id = o.id;
  END IF;

  UPDATE orders
     SET payment_status = 'paid', transaction_id = v_txn,
         status = CASE WHEN status = 'pending' THEN 'confirmed'::order_status ELSE status END
   WHERE id = o.id;
  RETURN 'paid';
END;
$$;

REVOKE ALL ON FUNCTION public.mark_order_paid(UUID, TEXT, BIGINT, TEXT, BOOLEAN) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.mark_order_paid(UUID, TEXT, BIGINT, TEXT, BOOLEAN) TO service_role;

-- ── 6. Profiles: staff can't delete or edit other team members ─
-- Orders outlive the account that placed them.
DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conname = 'orders_user_id_fkey' AND conrelid = 'public.orders'::regclass AND confdeltype <> 'n'
  ) THEN
    ALTER TABLE public.orders DROP CONSTRAINT orders_user_id_fkey;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'orders_user_id_fkey' AND conrelid = 'public.orders'::regclass
  ) THEN
    ALTER TABLE public.orders
      ADD CONSTRAINT orders_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.profiles(id) ON DELETE SET NULL;
  END IF;
END $$;

DROP POLICY IF EXISTS admin_profiles ON public.profiles;
DROP POLICY IF EXISTS admin_read_profiles ON public.profiles;
DROP POLICY IF EXISTS admin_update_profiles ON public.profiles;
DROP POLICY IF EXISTS owner_delete_profiles ON public.profiles;
CREATE POLICY admin_read_profiles ON public.profiles FOR SELECT USING (public.is_admin());
CREATE POLICY admin_update_profiles ON public.profiles FOR UPDATE USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY owner_delete_profiles ON public.profiles FOR DELETE USING (public.is_super_admin());

-- Only the owner (or the server) changes roles or account links; staff may
-- edit customers and their own row, never another team member's.
CREATE OR REPLACE FUNCTION public.guard_profile_privileges()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF COALESCE(auth.role(), 'service_role') IN ('anon', 'authenticated') AND NOT public.is_super_admin() THEN
    IF TG_OP = 'INSERT' THEN
      NEW.role := 'customer';
    ELSE
      IF NEW.role IS DISTINCT FROM OLD.role OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id THEN
        RAISE EXCEPTION 'Not allowed to change role or account link' USING ERRCODE = '42501';
      END IF;
      IF OLD.role::text <> 'customer' AND OLD.auth_user_id IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION 'Not allowed to change another team member' USING ERRCODE = '42501';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- ── 7. Team: confirmed accounts only ──────────────────────────
DROP FUNCTION IF EXISTS public.admin_profile_by_email(TEXT);

CREATE OR REPLACE FUNCTION public.admin_profile_by_email(p_email TEXT)
RETURNS TABLE(profile_id UUID, full_name TEXT, role TEXT, email_confirmed_at TIMESTAMPTZ, last_sign_in_at TIMESTAMPTZ)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'owner access required' USING ERRCODE = '42501';
  END IF;
  IF p_email IS NULL OR length(p_email) > 254 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT p.id, p.full_name, p.role::text, u.email_confirmed_at, u.last_sign_in_at
  FROM auth.users u
  JOIN profiles p ON p.auth_user_id = u.id
  WHERE lower(u.email) = lower(btrim(p_email))
  LIMIT 1;
END;
$$;

REVOKE ALL ON FUNCTION public.admin_profile_by_email(TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_profile_by_email(TEXT) TO authenticated, service_role;

-- ── 8. Rate limits: a negative cost gives hits back ───────────
CREATE OR REPLACE FUNCTION public.rate_limit_hit(
  p_key            TEXT,
  p_limit          INT,
  p_window_seconds INT,
  p_cost           INT DEFAULT 1
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_hits INT;
  v_cost INT := COALESCE(p_cost, 1);
BEGIN
  IF p_key IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_window_seconds IS NULL OR p_window_seconds < 1 THEN
    RAISE EXCEPTION 'invalid_rate_limit' USING ERRCODE = '22023';
  END IF;

  -- Refund (e.g. a promo code or sign-in that turned out fine): never below zero.
  IF v_cost < 0 THEN
    UPDATE rate_limits SET hits = GREATEST(hits + v_cost, 0)
     WHERE key = left(p_key, 200)
       AND window_start > now() - make_interval(secs => p_window_seconds);
    RETURN true;
  END IF;

  INSERT INTO rate_limits AS r (key, window_start, hits)
  VALUES (left(p_key, 200), now(), v_cost)
  ON CONFLICT (key) DO UPDATE SET
    hits = CASE WHEN r.window_start <= now() - make_interval(secs => p_window_seconds)
                THEN v_cost ELSE r.hits + v_cost END,
    window_start = CASE WHEN r.window_start <= now() - make_interval(secs => p_window_seconds)
                        THEN now() ELSE r.window_start END
  RETURNING hits INTO v_hits;

  -- Housekeeping: now and then, forget windows older than a day.
  IF random() < 0.02 THEN
    DELETE FROM rate_limits WHERE window_start < now() - interval '1 day';
  END IF;

  RETURN v_hits - v_cost < p_limit;
END;
$$;

REVOKE ALL ON FUNCTION public.rate_limit_hit(TEXT, INT, INT, INT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.rate_limit_hit(TEXT, INT, INT, INT) TO service_role;

-- ── 9. Contact form: only through the server (throttle + honeypot) ─
DROP POLICY IF EXISTS public_insert_contact ON public.contact_messages;

-- ── 10. Reviews: the public key reads public columns only ─────
REVOKE SELECT ON TABLE public.reviews FROM anon;
GRANT SELECT (id, product_id, rating, title, comment, author_name, is_verified, status, created_at)
  ON TABLE public.reviews TO anon;

NOTIFY pgrst, 'reload schema';

COMMIT;
